import{I as a}from"./sections-C5pUcMhT.js";const t=e=>String(+e.toFixed(1)),n=e=>e.name.replace("IPE","IPE "),s=a.map(e=>[n(e),e.w.toFixed(1),String(e.A),t(e.h*10),t(e.b*10),t(e.tw*10),t(e.tf*10),t(e.r*10),t((e.tf+e.r)*10),t((e.h-2*(e.tf+e.r))*10),(Math.round((e.h-2*e.tf)*e.tw*100+1e-6)/100).toFixed(2)]),r=a.map(e=>[n(e),String(e.Ix),String(e.Sx),e.rx.toFixed(2),String(e.Iy),String(e.Sy),e.ry.toFixed(2)]),i=[{id:"l.st-intro.build",xp:30,title:{en:"Erect the shed piece by piece, from the footings to the sheeting",ar:"ابني الهنجر حتة حتة، من القواعد لحد الصاج"},check:e=>e.mode==="build"&&e.complete},{id:"l.st-intro.roof",xp:20,title:{en:"Follow the roof load down to the footings",ar:"تابع حمل السقف لحد القواعد"},check:e=>e.path==="gravity"&&!e.pathBroken&&e.complete},{id:"l.st-intro.gable",xp:30,title:{en:"Follow the wind on the gable wall: which members does it cross?",ar:"تابع الرياح على حائط الواجهة: بتعدّي على أنهي أعضاء؟"},check:e=>e.path==="gableWind"&&!e.pathBroken&&e.complete},{id:"l.st-intro.sway",xp:30,title:{en:"Take out the roof bracing: nothing stops the frames swaying along the building",ar:"شيل شكالات السقف: مفيش حاجة تمنع الإزاحة الجانبية (Sway) للإطارات بطول المبنى"},check:e=>e.unstable==="sway"&&e.roofHidden}],o=[{id:"l.st-intro.odd",xp:20,title:{en:"Force an odd number of panels: which check fails?",ar:"خلّي عدد البواكي فردي: أنهي مراجعة بتقع؟"},check:e=>e.mode==="layout"&&!e.evenOk},{id:"l.st-intro.z10",xp:30,title:{en:"Force the 10:1 slope on the 26 m truss: h falls below 1.25 m and H has to grow",ar:"اجبر الميل 10:1 على جمالون الـ 26 م: h بتنزل تحت 1.25 م و H لازم تكبر"},check:e=>e.mode==="layout"&&e.Z===10&&e.H>2.5},{id:"l.st-intro.sub",xp:40,title:{en:"Steepen the upper chord until the N-truss diagonals pass 60°: the lab turns it into a sub-divided truss",ar:"ميّل الوتر العلوي لحد ما أقطار جمالون N تعدّي 60°: المعمل بيحوّله لجمالون مقسّم"},check:e=>e.mode==="layout"&&e.type==="subdivided"}],h=[{id:"l.st-intro.middle",xp:30,title:{en:"Lengthen the shed until a middle bracing bay appears",ar:"طوّل الهنجر لحد ما تظهر باكية شكالات في النص"},check:e=>e.braced>=3},{id:"l.st-intro.strut",xp:20,title:{en:"Lower the clear height below 6 m: the strut goes and one tier of X is enough",ar:"نزّل الارتفاع الصافي تحت 6 م: العضو الأفقي بيختفي ودور X واحد كفاية"},check:e=>e.tiers===1&&e.clear<6},{id:"l.st-intro.nov",xp:30,title:{en:"Take out the vertical bracing and watch the whole shed lean",ar:"شيل الشكالات الرأسية وشوف الهنجر كله بيميل"},check:e=>e.unstable==="sway"&&e.vertHidden}],l=[{id:"l.st-intro.factory",xp:40,title:{en:"Lay out the 19 × 50 m factory with a 6 m clear height and compare every step",ar:"خطّط المصنع 19 × 50 م بارتفاع صافي 6 م وقارن كل خطوة"},check:e=>e.mode==="layout"&&e.B===19&&e.L===50&&e.clear===6&&e.checksOk}],d=[{id:"l.st-intro.ws-angles",xp:30,title:{en:"Your workshop in Layout mode: which rule does its triangular truss break?",ar:"ورشتك في وضع التخطيط: الجمالون المثلث بتاعها بيكسر أنهي قاعدة؟"},check:e=>e.mode==="layout"&&e.B===12&&e.shape==="triangle"&&!e.anglesOk},{id:"l.st-intro.ws-trap",xp:40,title:{en:"Give the workshop a trapezoidal N-truss that passes every check",ar:"ادّي الورشة جمالون N شبه منحرف بيعدّي كل المراجعات"},check:e=>e.mode==="layout"&&e.B===12&&e.shape==="trapezoid"&&e.checksOk},{id:"l.st-intro.ws-crane",xp:20,title:{en:"Follow the crane loads of the workshop",ar:"تابع أحمال الونش في الورشة"},check:e=>e.path==="crane"&&!e.pathBroken}],c={sections:[{id:"why",title:{en:"Why steel for a factory",ar:"ليه الحديد في المصانع"},blocks:[{t:"p",text:{en:"A factory, a warehouse or a hangar asks for a large column-free floor, a light roof, a short building time and — often — the chance to extend or move the building later. Steel answers all four: it is strong in tension **and** compression, so a slender member carries a large force; it is made in a workshop and bolted on site, so there is no formwork and no curing; and a bolted building can be taken apart. The price is paid in **corrosion** (paint or galvanising and maintenance), **fire** (steel loses strength quickly when heated, so it may need protection) and **buckling**, the weakness of every slender compressed member.",ar:"المصنع أو المخزن أو الهانجر محتاج أرضية كبيرة من غير أعمدة، وسقف خفيف، ووقت تنفيذ قصير — وكتير كمان إمكانية إنك توسّع المبنى أو تنقله بعدين. الحديد بيحقق الأربعة: قوي في الشد **والضغط**، فعضو نحيف بيشيل قوة كبيرة؛ وبيتصنّع في الورشة ويتربط بمسامير في الموقع، فمفيش شدة ولا انتظار معالجة؛ والمبنى المربوط بمسامير ممكن يتفك. والتمن: **الصدأ** (دهان أو جلفنة وصيانة)، و**الحريق** (الحديد بيفقد مقاومته بسرعة لما يسخن، فممكن يحتاج حماية)، و**الانبعاج**، نقطة ضعف أي عضو نحيف مضغوط."}},{t:"table",head:[{en:"Steel",ar:"الحديد"},{en:"Reinforced concrete",ar:"الخرسانة المسلحة"}],rows:[[{en:"light: long spans, small foundations",ar:"خفيف: بحور كبيرة وقواعد صغيرة"},{en:"heavy: its own weight is most of the load",ar:"تقيلة: وزنها الذاتي أغلب الحمل"}],[{en:"fast: shop-made, bolted on site",ar:"سريع: بيتصنّع في الورشة ويتربط في الموقع"},{en:"formwork, casting and curing on site",ar:"شدة وصب ومعالجة في الموقع"}],[{en:"can be extended or dismantled",ar:"ممكن يتوسّع أو يتفك"},{en:"practically permanent",ar:"دايمة عمليًا"}],[{en:"needs paint, fire protection, bracing against buckling",ar:"محتاج دهان وحماية من الحريق وشكالات ضد الانبعاج"},{en:"durable and fire resistant",ar:"بتعمّر وبتقاوم الحريق"}],[{en:"easy to strengthen in service: a plate, a brace or a column is bolted or welded on",ar:"سهل في تدعيم المنشآت وهي شغالة: لوح أو شكالة أو عمود بيتربط بمسامير أو بيتلحم"},{en:"strengthening means jackets, formwork and curing",ar:"التدعيم معناه تقميص وشدة ومعالجة"}],[{en:"higher maintenance cost: the paint and the fire protection are renewed",ar:"تكلفة صيانة أعلى: الدهان والحماية من الحريق بيتجددوا"},{en:"little routine maintenance",ar:"صيانة دورية قليلة"}]],caption:{en:"Typical uses of steel: industrial sheds and hangars, high-rise frames, towers and masts, tanks, sign supports, bridges.",ar:"استخدامات الحديد المعتادة: الهناجر والمصانع، هياكل الأبراج العالية، الأبراج والصواري، الخزانات، حوامل اللوحات، والكباري."}},{t:"p",text:{en:"**Strengthening and upkeep.** The same bolts that let a steel building be taken apart make it the easiest one to **strengthen**: when a floor has to carry a new machine, a cover plate on a beam, an extra brace or a new column is added while the building stays in use. The two weaknesses, on the other hand, add up to a third one — a **high maintenance cost**, because the paint against rust and the fire protection have to be inspected and renewed through the whole life of the building. Where high-rise buildings use steel, it is for the first reason of all: very large loads call for a material that carries them in small sections.",ar:"**التدعيم والصيانة.** نفس المسامير اللي بتخلي المبنى المعدني يتفك بتخليه أسهل مبنى في **تدعيم المنشآت**: لما دور يحتاج يشيل ماكينة جديدة، لوح تغطية على كمرة أو شكالة زيادة أو عمود جديد بيتضافوا والمبنى شغال. وفي المقابل العيبين بيطلّعوا عيب تالت — **تكلفة صيانة عالية**، لأن دهان الصدأ والحماية من الحريق لازم يتراجعوا ويتجددوا طول عمر المبنى. ولما الأبراج العالية بتستخدم الحديد، فده علشان أول سبب خالص: الأحمال الكبيرة أوي محتاجة خامة تشيلها بقطاعات صغيرة."}},{t:"p",text:{en:"**How much lighter?** A reinforced-concrete roof slab 12 cm thick weighs $0.12\\times2500 = 300$ kg/m². A steel roof — corrugated sheets of about 6 kg/m² on purlins and trusses of about 24 kg/m² — weighs about 30 kg/m², a tenth of it. The material itself is dense ($\\rho = 7.85$ t/m³, $E = 2100$ t/cm²) but it is used in thin sections: an IPE 300 of 53.8 cm² weighs $53.8\\times10^{-4}\\times7850 = 42.2$ kg per metre, so a 12 m length is about 506 kg.",ar:"**أخف بقد إيه؟** بلاطة سقف خرسانية تخانتها 12 سم وزنها $0.12\\times2500 = 300$ كجم/م². وسقف معدني — ألواح صاج مموج حوالي 6 كجم/م² على مدادات وجمالونات حوالي 24 كجم/م² — وزنه حوالي 30 كجم/م²، يعني العُشر. الخامة نفسها تقيلة ($\\rho = 7.85$ t/m³ و $E = 2100$ t/cm²) لكنها بتتستخدم في قطاعات رفيعة: الـ IPE 300 مساحته 53.8 سم² ووزنه $53.8\\times10^{-4}\\times7850 = 42.2$ كجم للمتر، يعني طول 12 م حوالي 506 كجم."}},{t:"quiz",q:{kind:"num",q:{en:"A 16 cm RC roof slab (2500 kg/m³) against a steel roof of 32 kg/m²: how many times heavier is the slab?",ar:"بلاطة سقف خرسانية 16 سم (2500 كجم/م³) قصاد سقف معدني 32 كجم/م²: البلاطة أتقل كام مرة؟"},answer:12.5,tol:.005,explain:{en:"$0.16\\times2500 = 400$ kg/m², and $400/32 = 12.5$.",ar:"$0.16\\times2500 = 400$ كجم/م²، و $400/32 = 12.5$."}}}]},{id:"sections",title:{en:"Rolled sections and their tables",ar:"القطاعات المدرفلة وجداولها"},blocks:[{t:"p",text:{en:"The mills roll a family of standard shapes, and the designer picks from their tables: **I-sections** — the old tapered-flange IPN (S.I.B), the parallel-flange **IPE** (the most used beam) and the broad-flange **HEA / HEB / HEM** (columns: the flange is as wide as the section is deep); **channels UPN** (purlins, girts, built-up columns); **equal and unequal angles** (truss members, bracing); **plates** (gussets, built-up girders); **tubes, boxes and tees**. A rolled bar is transported in lengths of up to about **12 m**, so a longer member is spliced.",ar:"مصانع الدرفلة بتطلع عيلة من الأشكال القياسية، والمصمم بيختار من جداولها: **قطاعات I** — القديم IPN (S.I.B) بشفة مايلة، و**IPE** بشفة متوازية (أكتر كمرة بتتستخدم)، والعريض **HEA / HEB / HEM** (للأعمدة: الشفة عرضها قد عمق القطاع)؛ و**المجاري UPN** (المدادات والـ Girts والأعمدة المركبة)؛ و**الزوايا المتساوية والمختلفة** (أعضاء الجمالونات والشكالات)؛ و**الألواح** (ألواح الوصلة (Gusset) والكمرات الملحومة)؛ و**المواسير والصناديق والقطاعات T**. القطاع المدرفل بيتنقل بأطوال لحد حوالي **12 م**، فالعضو الأطول بيتوصّل."}},{t:"p",text:{en:"**Reading a table.** The number of a section is its depth in millimetres: an IPE 360 is 360 mm deep, a UPN 160 is 160 mm. Each row gives the **weight** in kg per running metre, the **area** in cm², the plate dimensions in mm, and the properties in centimetre units — $I$ in cm⁴, the elastic section modulus $S$ in cm³ (it comes back with bending), $r$ in cm. The weight is simply the area times the density: one square centimetre of steel one metre long weighs $10^{-4}\\times7850 = 0.785$ kg, so an IPE 360 of 72.7 cm² weighs $72.7\\times0.785 = 57.1$ kg/m — the value its row prints.",ar:"**إزاي تقرا الجدول.** رقم القطاع هو عمقه بالمليمتر: الـ IPE 360 عمقه 360 مم، والـ UPN 160 عمقه 160 مم. كل سطر بيدّي **الوزن** بالكيلو للمتر الطولي، و**المساحة** بالسم²، وأبعاد الألواح بالمم، والخواص بوحدات السنتيمتر — $I$ بالسم⁴، ومعاير القطاع المرن $S$ بالسم³ (هيرجع معانا في الانحناء)، و $r$ بالسم. والوزن ببساطة المساحة في الكثافة: سنتيمتر مربع حديد طوله متر وزنه $10^{-4}\\times7850 = 0.785$ كجم، فالـ IPE 360 اللي مساحته 72.7 سم² وزنه $72.7\\times0.785 = 57.1$ كجم/م — نفس الرقم اللي في سطره."}},{t:"p",text:{en:"A table row gives the dimensions $h, b, t_w, t_f$ and the properties $A$, $I_x$, $S_x$, $r_x$, $I_y$, $S_y$, $r_y$ (and the weight per metre). The radius of gyration measures how far the area is spread from an axis, and it decides buckling:",ar:"سطر الجدول بيدّي الأبعاد $h, b, t_w, t_f$ والخواص $A$ و $I_x$ و $S_x$ و $r_x$ و $I_y$ و $S_y$ و $r_y$ (والوزن للمتر). نصف قطر القصور بيقيس المساحة موزعة بعيد عن المحور قد إيه، وهو اللي بيحكم الانبعاج:"}},{t:"eq",tex:["r = \\sqrt{\\dfrac{I}{A}}"],caption:{en:"I = second moment of area about the axis, A = area of the section.",ar:"I = عزم القصور حوالين المحور، و A = مساحة القطاع."}},{t:"p",text:{en:"**Example.** IPE 300: $r_x = \\sqrt{8356/53.8} = 12.46$ cm but $r_y = \\sqrt{604/53.8} = 3.35$ cm — almost four times smaller, so an IPE column would buckle about its weak axis long before its strong one. HEB 300 spreads its flanges: $r_x = \\sqrt{25170/149} = 13.0$ cm and $r_y = \\sqrt{8563/149} = 7.58$ cm, a much more balanced column. That is why the broad-flange sections carry the columns of a shed, and why a column is turned so that the plane where it bends most — the plane of the truss — uses its **strong axis** (its web lies in that plane), while bracing along the building holds its weak axis.",ar:"**مثال.** IPE 300: $r_x = \\sqrt{8356/53.8} = 12.46$ سم لكن $r_y = \\sqrt{604/53.8} = 3.35$ سم — أصغر تقريبًا أربع مرات، فعمود IPE هينبعج حوالين محوره الضعيف قبل القوي بكتير. الـ HEB 300 شفته عريضة: $r_x = \\sqrt{25170/149} = 13.0$ سم و $r_y = \\sqrt{8563/149} = 7.58$ سم، عمود متوازن أكتر بكتير. علشان كده القطاعات العريضة هي اللي بتشيل أعمدة الهنجر، وعلشان كده العمود بيتلف بحيث المستوى اللي بيتحني فيه أكتر — مستوى الجمالون — يستخدم **محوره القوي** (العصب في المستوى ده)، والشكالات بطول المبنى هي اللي ماسكة محوره الضعيف."}},{t:"p",text:{en:"Three columns of the full table need a word. $r_1$ is the **root radius**, the curved fillet that joins the web to each flange. $c = t_f + r_1$ is the distance from the outer face of a flange to the end of that fillet, so $h - 2c$ is the **straight part of the web** — the only depth where a connection plate, a cleat or a row of bolts sits flat on the web. $A_{web} = (h - 2t_f)\\,t_w$ is the area of the web between the flanges, used later for shear. **Example — IPE 400:** $c = 13.5 + 21 = 34.5$ mm, $h - 2c = 400 - 69 = 331$ mm, and $A_{web} = (400 - 27)\\times8.6 = 3208$ mm² $= 32.1$ cm².",ar:"تلات أعمدة في الجدول الكامل محتاجين كلمة. $r_1$ هو **نصف قطر التدوير (Root radius)**، الركنية المقوّسة اللي بتوصل العصب بكل شفة. و $c = t_f + r_1$ هي المسافة من الوش الخارجي للشفة لحد آخر الركنية دي، فـ $h - 2c$ هو **الجزء المستقيم من العصب** — العمق الوحيد اللي لوح وصلة أو زاوية تثبيت أو صف مسامير يقعد عليه مفرود على العصب. و $A_{web} = (h - 2t_f)\\,t_w$ مساحة العصب بين الشفتين، وهتستخدم بعدين في القص. **مثال — IPE 400:** $c = 13.5 + 21 = 34.5$ مم، و $h - 2c = 400 - 69 = 331$ مم، و $A_{web} = (400 - 27)\\times8.6 = 3208$ مم² $= 32.1$ سم²."}},{t:"table",head:["IPE",{en:"kg/m",ar:"كجم/م"},"$A$ (cm²)","$h$","$b$","$t_w$","$t_f$","$r_1$","$c$","$h-2c$","$A_{web}$ (cm²)"],rows:s,caption:{en:"Parallel-flange I-sections IPE 80–600: weight, area and dimensions (h, b, t_w, t_f, r₁, c and h − 2c in mm).",ar:"قطاعات I بشفة متوازية IPE 80–600: الوزن والمساحة والأبعاد (h و b و t_w و t_f و r₁ و c و h − 2c بالمم)."}},{t:"table",head:["IPE","$I_x$ (cm⁴)","$S_x$ (cm³)","$r_x$ (cm)","$I_y$ (cm⁴)","$S_y$ (cm³)","$r_y$ (cm)"],rows:r,caption:{en:"The same sections: properties about the strong axis x (in the web plane) and the weak axis y.",ar:"نفس القطاعات: الخواص حوالين المحور القوي x (في مستوى العصب) والمحور الضعيف y."}},{t:"p",text:{en:"Two constants complete the tables: the density $\\rho = 7.85$ t/m³ (about 77 kN/m³) and the modulus of elasticity $E = 2100$ t/cm² (about 206 000 N/mm²). $E$ is **the same for every grade of steel**: a stronger grade raises the yield stress, not the stiffness, so choosing St 52 instead of St 37 changes neither an elastic deflection nor the Euler buckling load of a slender member.",ar:"تابتين بيكمّلوا الجداول: الكثافة $\\rho = 7.85$ t/m³ (حوالي 77 kN/m³) ومعاير المرونة $E = 2100$ t/cm² (حوالي 206000 N/mm²). الـ $E$ **واحد لكل أنواع الحديد**: الرتبة الأقوى بترفع إجهاد الخضوع مش الجساءة، فلو اخترت St 52 بدل St 37 لا الترخيم المرن هيتغير ولا حمل الانبعاج بتاع أويلر لعضو نحيف."}},{t:"quiz",q:{kind:"num",q:{en:"HEB 200: A = 78.1 cm², I_x = 5696 cm⁴. r_x (cm)?",ar:"HEB 200: A = 78.1 سم² و I_x = 5696 سم⁴. r_x (سم)؟"},answer:8.54,tol:.004,unit:"cm",explain:{en:"$r_x = \\sqrt{5696/78.1} = \\sqrt{72.93} = 8.54$ cm, as the table gives.",ar:"$r_x = \\sqrt{5696/78.1} = \\sqrt{72.93} = 8.54$ سم، زي ما الجدول بيقول."}}}]},{id:"parts",title:{en:"The shed, piece by piece — and where every load goes",ar:"الهنجر حتة حتة — وكل حمل بيروح فين"},blocks:[{t:"p",text:{en:"**Four stages.** A steel building is designed in the same four stages as a concrete one, and this episode is the first of them:",ar:"**أربع مراحل.** المبنى المعدني بيتصمم على نفس الأربع مراحل بتوع المبنى الخرساني، والحلقة دي هي أولهم:"}},{t:"steps",items:[{en:"**General layout** — every structural element drawn in its place, with assumed approximate sizes.",ar:"**التخطيط العام (Layout)** — كل عنصر إنشائي مرسوم في مكانه، بمقاسات تقريبية مفترضة."},{en:"**Loads** — the dead, live, wind and crane loads that reach each element (the loads episode).",ar:"**الأحمال** — الأحمال الميتة والحية والرياح والونش اللي بتوصل لكل عنصر (حلقة الأحمال)."},{en:"**Design** — every element is checked and its real section replaces the assumed one.",ar:"**التصميم** — كل عنصر بيتراجع وقطاعه الحقيقي بياخد مكان المفترض."},{en:"**Detail (shop) drawings** — the joints and members drawn for the workshop that cuts, drills and welds them.",ar:"**اللوحات التنفيذية (Shop drawings)** — الوصلات والأعضاء مرسومة للورشة اللي بتقصها وتخرمها وتلحمها."}]},{t:"p",text:{en:"A steel shed is a chain of simple elements, each carrying the one above it. **Sheeting** (corrugated sheets about 0.5 mm thick, single-skin or sandwich panels) spans between **purlins** — light channels running along the building at every top joint of the trusses. The purlins rest on the **main system**: trusses or portal frames spanning across the building, one every S metres. The trusses sit on **columns**, the columns on **footings**. On the walls, **side girts** (horizontal members between the columns) carry the wall cladding, and in the end walls **end girts** span between **gable columns**. Three systems of **bracing** make the whole thing stable: **roof (horizontal) bracing**, **vertical bracing** in the walls, and **longitudinal bracing** between the trusses. A **crane girder** on brackets may run along the columns.",ar:"الهنجر المعدني سلسلة من عناصر بسيطة، كل واحد شايل اللي فوقه. **الصاج** (ألواح مموجة تخانتها حوالي 0.5 مم، طبقة واحدة أو ساندوتش) بيرتكز على **المدادات** — مجاري خفيفة ماشية بطول المبنى عند كل عقدة علوية في الجمالونات. المدادات راكبة على **النظام الرئيسي**: جمالونات أو إطارات ماشية بعرض المبنى، واحد كل S متر. الجمالونات قاعدة على **الأعمدة**، والأعمدة على **القواعد**. وعلى الحوائط **الـ Girts الجانبية** (أعضاء أفقية بين الأعمدة) شايلة تكسية الحائط، وفي الحوائط الطرفية **Girts طرفية** بين **أعمدة الواجهة (Gable)**. وتلات أنظمة **شكالات** بتخلي الحاجة كلها مستقرة: **شكالات السقف الأفقية**، و**الشكالات الرأسية** في الحوائط، و**الشكالات الطولية** بين الجمالونات. وممكن **كمرة ونش** تمشي على كوابيل بطول الأعمدة."}},{t:"table",head:[{en:"Role",ar:"الدور"},{en:"Concrete hall",ar:"الصالة الخرسانية"},{en:"Steel shed",ar:"الهنجر المعدني"}],rows:[[{en:"roof surface",ar:"سطح السقف"},{en:"slab, at least 10 cm (250 kg/m² and more)",ar:"بلاطة، 10 سم على الأقل (250 كجم/م² وأكتر)"},{en:"corrugated sheets about 0.5 mm (about 6 kg/m²)",ar:"صاج مموج حوالي 0.5 مم (حوالي 6 كجم/م²)"}],[{en:"secondary members",ar:"العناصر الثانوية"},{en:"secondary beams",ar:"كمرات متشالة (ثانوية)"},{en:"purlins: small channels",ar:"المدادات: مجاري صغيرة"}],[{en:"main system",ar:"النظام الرئيسي"},{en:"frames or girders",ar:"إطارات أو كمرات كبيرة"},{en:"trusses or portal frames",ar:"جمالونات أو إطارات"}],[{en:"down to the ground",ar:"لحد الأرض"},{en:"columns → footings",ar:"الأعمدة ← القواعد"},{en:"columns → footings",ar:"الأعمدة ← القواعد"}],[{en:"ties along the building",ar:"الربط بطول المبنى"},{en:"deep beams and the slab",ar:"كمرات عميقة والبلاطة"},{en:"only the bracing",ar:"الشكالات بس"}]],caption:{en:"The same chain in both materials — except the last row: a steel shed has nothing that ties its frames together until bracing is added.",ar:"نفس السلسلة في الخامتين — ما عدا الصف الأخير: الهنجر المعدني مفيهوش حاجة بتربط إطاراته ببعض لحد ما الشكالات تتضاف."}},{t:"p",text:{en:"**Purlins.** One purlin sits on every top joint of the truss, so that the roof load reaches the truss at its joints and the purlin spacing equals the panel $a$; at the ridge there are two, one at the top of each slope. They are small channels, and a channel is always laid with its **opening facing up the slope** (its toes towards the ridge). A channel loaded on its flange twists, because its shear centre lies outside the web; laid this way, that twist turns it up the slope and works against the down-slope component of the roof load, which tries to roll it over.",ar:"**المدادات.** على كل عقدة علوية في الجمالون مداد، علشان حمل السقف يوصل للجمالون عند عقده، والمسافة بين المدادات تبقى هي الباكية $a$؛ وعند الـ Ridge فيه اتنين، واحد في أعلى كل ميل. المدادات مجاري صغيرة، والمجرى دايمًا بيتحط و**فتحته لفوق الميل** (أطرافه ناحية الـ Ridge). المجرى المتحمّل على شفته بيلف، لأن مركز القص بتاعه برّه العصب؛ ولما يتحط كده، اللفة دي بتلفه ناحية فوق الميل وبتعاكس مركبة حمل السقف اللي بطول الميل، اللي بتحاول تقلبه لتحت."}},{t:"p",text:{en:"**Why a truss for a large span?** A beam has to get deeper as its span grows — the moment grows with the square of the span, and depth is what resists it. A solid web that deep would be very heavy. A truss keeps its material in two chords far apart and leaves the middle **open**, crossed only by slender web members, so it can be two or three metres deep and still weigh little. That is why the truss is the usual main system of a wide shed, and the portal frame (next episode) the alternative for moderate spans.",ar:"**ليه جمالون للبحر الكبير؟** الكمرة لازم يزيد عمقها كل ما بحرها يكبر — العزم بيزيد مع مربع البحر، والعمق هو اللي بيقاومه. وعصب مصمت بالعمق ده هيبقى تقيل أوي. الجمالون بيحط خامته في وترين بعاد عن بعض وبيسيب النص **مفرّغ**، مافيهوش غير أعضاء عصب نحيفة، فيقدر يبقى عمقه مترين أو تلاتة ووزنه قليل. علشان كده الجمالون هو النظام الرئيسي المعتاد للهنجر العريض، والإطار (الحلقة الجاية) البديل للبحور المتوسطة."}},{t:"table",head:[{en:"Load",ar:"الحمل"},{en:"Path to the ground",ar:"مساره للأرض"}],rows:[[{en:"roof load (dead + live)",ar:"حمل السقف (ميت + حي)"},{en:"sheeting → purlins → trusses (joint loads) → columns → footings",ar:"الصاج ← المدادات ← الجمالونات (أحمال عقد) ← الأعمدة ← القواعد"}],[{en:"wind on a side wall",ar:"رياح على حائط جانبي"},{en:"cladding → side girts → columns → the frame (columns + truss) → footings",ar:"التكسية ← الـ Girts الجانبية ← الأعمدة ← الإطار (أعمدة + جمالون) ← القواعد"}],[{en:"wind on the gable wall",ar:"رياح على حائط الواجهة"},{en:"cladding → end girts → gable columns → roof bracing → vertical bracing → footings",ar:"التكسية ← الـ Girts الطرفية ← أعمدة الواجهة ← شكالات السقف ← الشكالات الرأسية ← القواعد"}],[{en:"crane braking along the building",ar:"فرامل الونش بطول المبنى"},{en:"crane girder → vertical bracing → footings",ar:"كمرة الونش ← الشكالات الرأسية ← القواعد"}]]},{t:"p",text:{en:"Across the building each frame is stable by itself (fixed column bases and the truss tying the column tops). **Along** the building the frames are just a row of cards: without the bracing, the gable wind or a braking crane would push them over like dominoes. The bracing is therefore not an extra — it is the only way those loads reach the ground.",ar:"بعرض المبنى كل إطار مستقر لوحده (قواعد أعمدة ثابتة والجمالون رابط رؤوس الأعمدة). لكن **بطول** المبنى الإطارات مجرد صف كوتشينة: من غير الشكالات، رياح الواجهة أو فرامل الونش هتوقّعهم زي الدومينو. يبقى الشكالات مش حاجة زيادة — هي الطريق الوحيد اللي الأحمال دي بتوصل بيه للأرض."}},{t:"p",text:{en:"**Why a concrete hall needs no bracing system.** Its frames are tied along the building by beams around 60 cm deep and by a slab at least 10 cm thick that acts as a stiff diaphragm. In a steel shed the only members along the building are the purlins, about 16 cm deep, and sheets half a millimetre thick. Compare one tie: a 300 × 600 mm concrete beam has $I = 30\\times60^3/12 = 540\\,000$ cm⁴, a UPN 160 purlin only 925 cm⁴; even with $E_c \\approx 22\\,000$ N/mm² against $E_s \\approx 206\\,000$ N/mm², the concrete tie is $\\dfrac{22\\,000\\times540\\,000}{206\\,000\\times925} \\approx 62$ times stiffer — and the slab is $100/0.5 = 200$ times thicker than the sheet. The steel shed must be given its own ties and diagonals: the bracing.",ar:"**ليه الصالة الخرسانية مش محتاجة نظام شكالات.** إطاراتها مربوطة بطول المبنى بكمرات عمقها حوالي 60 سم وببلاطة تخانتها 10 سم على الأقل بتشتغل كديافرام جاسئ. لكن في الهنجر المعدني الأعضاء الوحيدة اللي بطول المبنى هي المدادات، عمقها حوالي 16 سم، وصاج تخانته نص مليمتر. قارن رباط واحد: كمرة خرسانية 300 × 600 مم عزم قصورها $I = 30\\times60^3/12 = 540\\,000$ سم⁴، ومداد UPN 160 عزم قصوره 925 سم⁴ بس؛ وحتى مع $E_c \\approx 22\\,000$ N/mm² قصاد $E_s \\approx 206\\,000$ N/mm²، الرباط الخرساني أجسأ $\\dfrac{22\\,000\\times540\\,000}{206\\,000\\times925} \\approx 62$ مرة — والبلاطة أتخن من الصاج $100/0.5 = 200$ مرة. يبقى الهنجر المعدني لازم ياخد روابطه وأقطاره الخاصة: الشكالات."}},{t:"lab",lab:"shed",height:500,props:{preset:"assemble",missions:i,defaultTab:"inputs"},caption:{en:"Erect an 18 × 36 m shed with the + button, then pick a load in the toolbar and follow it. Click any member to read its role.",ar:"ابني هنجر 18 × 36 م بزرار +، وبعدين اختار حمل من شريط الأدوات وتابعه. اضغط على أي عضو عشان تقرا دوره."}},{t:"quiz",q:{kind:"mcq",q:{en:"Which element takes the wind on the gable wall up to the roof bracing?",ar:"أنهي عنصر بيطلّع رياح حائط الواجهة لشكالات السقف؟"},options:[{en:"the gable (end) columns",ar:"أعمدة الواجهة (Gable)"},{en:"the purlins",ar:"المدادات"},{en:"the lower chord of the trusses",ar:"الوتر السفلي للجمالونات"}],answer:0,explain:{en:"End girts hand the wind to the gable columns; each column spans from its footing to the roof and gives about half its load to the roof bracing.",ar:"الـ Girts الطرفية بتسلّم الرياح لأعمدة الواجهة؛ وكل عمود بحره من قاعدته للسقف وبيدّي حوالي نص حمله لشكالات السقف."}}}]},{id:"direction",title:{en:"Across the short side, one every 5–8 m",ar:"بعرض الضلع القصير، واحد كل 5–8 م"},blocks:[{t:"p",text:{en:"**The main trusses always span the short direction** of the building. The truss is the expensive element; its weight grows with its span, while the long direction is covered cheaply by purlins, girts and bracing between the frames. The columns are then turned with their strong axis (web) in the plane of the trusses.",ar:"**الجمالونات الرئيسية دايمًا ماشية في الاتجاه القصير** للمبنى. الجمالون هو العنصر الغالي؛ ووزنه بيزيد مع بحره، والاتجاه الطويل بيتغطى برخص بالمدادات والـ Girts والشكالات بين الإطارات. وبعدين الأعمدة بتتلف بمحورها القوي (العصب) في مستوى الجمالونات."}},{t:"p",text:{en:"The spacing S of the trusses — the span of the purlins — is kept between **5 and 8 m**: closer, and there are too many trusses; wider, and the purlins become heavy. Divide the length into a **whole number** of equal spacings:",ar:"المسافة S بين الجمالونات — يعني بحر المدادات — بتتاخد بين **5 و 8 م**: لو أقل الجمالونات تبقى كتير؛ ولو أكتر المدادات تتقل. قسّم الطول لـ **عدد صحيح** من المسافات المتساوية:"}},{t:"eq",tex:["n = \\dfrac{L}{5\\,\\sim\\,8}\\ \\ \\Rightarrow\\ \\ n\\ \\in\\ \\mathbb{N},\\qquad S = \\dfrac{L}{n}"],caption:{en:"L = length of the building; n = number of spacings (bays); prefer a round S near 6 m.",ar:"L = طول المبنى؛ و n = عدد المسافات (الباكيات)؛ ويفضل S رقم مقفول قريب من 6 م."}},{t:"p",text:{en:"**Example.** A 20 × 48 m hall: the trusses span the 20 m. $48/8 = 6$ and $48/5 = 9.6$, so 6 to 9 bays are possible: 8 bays of 6.0 m (or 6 of 8.0 m, 7 of 6.86 m …). Eight bays of 6 m give a round spacing in the middle of the range.",ar:"**مثال.** صالة 20 × 48 م: الجمالونات على الـ 20 م. $48/8 = 6$ و $48/5 = 9.6$، يعني من 6 لـ 9 باكيات ممكن: 8 باكيات كل واحدة 6.0 م (أو 6 كل واحدة 8.0 م، أو 7 كل واحدة 6.86 م …). التمن باكيات بـ 6 م بيدّوا مسافة مقفولة في نص المدى."}},{t:"quiz",q:{kind:"num",q:{en:"A shed 63 m long: how many bays give a whole-metre spacing within 5–8 m?",ar:"هنجر طوله 63 م: كام باكية بتدّي مسافة بالمتر الصحيح بين 5 و 8 م؟"},answer:9,tol:.001,explain:{en:"$63/8 = 7.9$ to $63/5 = 12.6$ → 8 to 12 bays; only 9 gives a whole number: 9 × 7 m.",ar:"$63/8 = 7.9$ لحد $63/5 = 12.6$ ← من 8 لـ 12 باكية؛ الـ 9 بس اللي بتدّي رقم صحيح: 9 × 7 م."}}}]},{id:"truss",title:{en:"The truss: depth, slope, panels and type",ar:"الجمالون: العمق والميل والبواكي والنوع"},blocks:[{t:"p",text:{en:"A roof truss is shaped by a few rules of thumb. Its depth at mid-span is **H = span/(12–16)**. At the column it keeps at least **h = 1.25 m**, enough to connect both chords to the column and to carry the end shear. Between the two, the upper chord slopes at **Z:1** — from 5:1 to 20:1, usually 10:1 or 20:1 (flatter, down to 40:1, when the depths are fixed first — see below) — to drain the roof. The **clear height** is measured from the floor to the lower chord at the column — the underside of the truss; the column rises a further h, to the upper chord, so its height is the clear height + h. The procedure:",ar:"الجمالون بيتشكّل بشوية قواعد عملية. عمقه في النص **H = البحر/(12–16)**. وعند العمود بيفضل على الأقل **h = 1.25 م**، كفاية نوصّل الوترين في العمود ونشيل القص عند الطرف. وبينهم الوتر العلوي مايل بميل **Z:1** — من 5:1 لـ 20:1، والمعتاد 10:1 أو 20:1 (وأفلطح، لحد 40:1، لما الأعماق تتحدد الأول — شوف تحت) — علشان المية تنزل. و**الارتفاع الصافي** بيتقاس من الأرضية لحد الوتر السفلي عند العمود — يعني بطن الجمالون؛ والعمود بيطلع فوقه كمان h لحد الوتر العلوي، فارتفاعه = الارتفاع الصافي + h. الطريقة:"}},{t:"steps",items:[{en:"Take H from span/(12–16) (the deeper end is safer for deflection).",ar:"خد H من البحر/(12–16) (الناحية الأعمق أأمن للترخيم)."},{en:"Try the slope 10:1: $h = H - \\dfrac{B}{2}\\cdot\\dfrac{1}{10}$. If $h \\ge 1.25$ m, keep it.",ar:"جرّب ميل 10:1: $h = H - \\dfrac{B}{2}\\cdot\\dfrac{1}{10}$. لو $h \\ge 1.25$ م، خليه."},{en:"Otherwise try 20:1. If h is still below 1.25 m, take h = 1.25 m and raise H: $H = h + \\dfrac{B}{2}\\cdot\\dfrac{1}{Z}$.",ar:"وإلا جرّب 20:1. لو h لسه أقل من 1.25 م، خد h = 1.25 م وكبّر H: $H = h + \\dfrac{B}{2}\\cdot\\dfrac{1}{Z}$."},{en:"Panels (= purlin spacing): $a \\approx \\dfrac{H + h}{2}$, kept within 1.5–2 m; the number of panels must be **even** (a joint at the ridge, carrying a purlin for each slope); then $a = B/n$ — it need not be a round number.",ar:"البواكي (= المسافة بين المدادات): $a \\approx \\dfrac{H + h}{2}$، في حدود 1.5–2 م؛ وعدد البواكي لازم يبقى **زوجي** (عقدة عند الـ Ridge شايلة مداد لكل ميل)؛ وبعدين $a = B/n$ — ومش لازم تطلع رقم مقفول."},{en:"Check the diagonals: $\\tan^{-1}(h/a)$ and $\\tan^{-1}(H/a)$ between 30° and 60°. Flatter diagonals carry large forces; steeper ones are long and make crowded joints.",ar:"راجع الأقطار: $\\tan^{-1}(h/a)$ و $\\tan^{-1}(H/a)$ بين 30° و 60°. القطري المفلطح بيشيل قوى كبيرة؛ والمايل أوي بيبقى طويل وبيزحم العقد."}]},{t:"p",text:{en:"**Example — a 26 m span.** $H = 26/12 = 2.17 \\to 2.15$ m. At 10:1: $h = 2.15 - 13/10 = 0.85 < 1.25$ ✗; at 20:1: $h = 2.15 - 13/20 = 1.50$ m ✓. So H = 2.15 m, h = 1.50 m, slope 20:1. Then $a \\approx (2.15 + 1.50)/2 = 1.825$ m, $26/1.825 = 14.2$ → **14 panels**, $a = 26/14 = 1.857$ m; angles $\\tan^{-1}(1.50/1.857) = 38.9°$ and $\\tan^{-1}(2.15/1.857) = 49.2°$ ✓.",ar:"**مثال — بحر 26 م.** $H = 26/12 = 2.17 \\to 2.15$ م. عند 10:1: $h = 2.15 - 13/10 = 0.85 < 1.25$ ✗؛ عند 20:1: $h = 2.15 - 13/20 = 1.50$ م ✓. يبقى H = 2.15 م و h = 1.50 م والميل 20:1. وبعدين $a \\approx (2.15 + 1.50)/2 = 1.825$ م، و $26/1.825 = 14.2$ ← **14 باكية**، و $a = 26/14 = 1.857$ م؛ والزوايا $\\tan^{-1}(1.50/1.857) = 38.9°$ و $\\tan^{-1}(2.15/1.857) = 49.2°$ ✓."}},{t:"p",text:{en:"**When the depths are fixed first.** The procedure raises H when h falls short at 20:1. Some layouts keep the chosen H instead, set h = 1.25 m and let the slope follow from the two depths, $Z = \\dfrac{B/2}{H - h}$ — flatter than 20:1. **Example — a 24 m truss** with H chosen at 1.55 m (inside $24/16 = 1.50$ to $24/12 = 2.00$ ✓): 20:1 gives $h = 1.55 - 0.60 = 0.95$ m ✗. The procedure would take h = 1.25 m and $H = 1.25 + 0.60 = 1.85$ m; keeping H = 1.55 m with h = 1.25 m gives $Z = 12/0.30 = 40$ → **40:1**, a ridge 0.30 m lower, and a longitudinal line x metres from the column $1.25 + x/40$ deep. Sixteen panels of 1.5 m still put the diagonals at 39.8° and 45.9° ✓.",ar:"**لما الأعماق تتحدد الأول.** الطريقة بتكبّر H لما h تطلع ناقصة عند 20:1. وفيه تخطيطات بتحتفظ بالـ H اللي اختارتها، وتاخد h = 1.25 م، وتسيب الميل يطلع من العمقين، $Z = \\dfrac{B/2}{H - h}$ — أفلطح من 20:1. **مثال — جمالون 24 م** و H مختارة 1.55 م (جوه $24/16 = 1.50$ لحد $24/12 = 2.00$ ✓): الـ 20:1 بتدّي $h = 1.55 - 0.60 = 0.95$ م ✗. الطريقة كانت هتاخد h = 1.25 م و $H = 1.25 + 0.60 = 1.85$ م؛ لكن لو فضلت H = 1.55 م مع h = 1.25 م يبقى $Z = 12/0.30 = 40$ ← **40:1**، والـ Ridge أوطى بـ 0.30 م، وخط الشكالات الطولية اللي على بعد x متر من العمود عمقه $1.25 + x/40$. وستاشر باكية كل واحدة 1.5 م لسه بيخلّوا الأقطار عند 39.8° و 45.9° ✓."}},{t:"p",text:{en:"**Why a between h and H?** The flattest diagonal spans one panel over the depth h, the steepest over the depth H. The first stays at 30° or more if $a \\le \\sqrt3\\,h$, the second at 60° or less if $a \\ge H/\\sqrt3$:",ar:"**ليه a بين h و H؟** أفلطح قطري بيغطي باكية واحدة على العمق h، وأميل قطري على العمق H. الأول بيفضل 30° أو أكتر لو $a \\le \\sqrt3\\,h$، والتاني 60° أو أقل لو $a \\ge H/\\sqrt3$:"}},{t:"eq",tex:["\\dfrac{H}{\\sqrt3} \\ \\le\\ a \\ \\le\\ \\sqrt3\\,h"],caption:{en:"Any panel between h and H satisfies both limits whenever H ≤ √3·h — always the case for an N-truss of up to 34 m at 20:1, where the angle check becomes a confirmation. At the steeper 10:1, H can exceed √3·h (a 40 m truss: H = 3.30 m, h = 1.30 m); then the window is narrower than h … H and the check really decides.",ar:"أي باكية بين h و H بتحقق الحدين طول ما H ≤ √3·h — وده متحقق دايمًا في جمالون N لحد 34 م بميل 20:1، وساعتها مراجعة الزوايا بتبقى مجرد تأكيد. لكن بالميل الأشد 10:1 ممكن H تعدّي √3·h (جمالون 40 م: H = 3.30 م و h = 1.30 م)؛ وساعتها الشباك بيبقى أضيق من h … H والمراجعة هي اللي بتحكم."}},{t:"p",text:{en:"For the 26 m truss the window is $2.15/\\sqrt3 = 1.24$ m to $\\sqrt3\\times1.50 = 2.60$ m; the chosen $a = 1.857$ m sits well inside it, and so does any panel of 1.5–2 m.",ar:"في جمالون الـ 26 م الشباك من $2.15/\\sqrt3 = 1.24$ م لحد $\\sqrt3\\times1.50 = 2.60$ م؛ والـ $a = 1.857$ م اللي اخترناها جوّاه بمسافة، وكمان أي باكية من 1.5 لـ 2 م."}},{t:"table",head:[{en:"Truss type",ar:"نوع الجمالون"},{en:"Used for",ar:"بيتستخدم لـ"}],rows:[[{en:"N (Pratt) or W truss, a = 1.5–2 m",ar:"جمالون N (Pratt) أو W، و a = 1.5–2 م"},{en:"spans up to about 34 m — the first choice",ar:"بحور لحد حوالي 34 م — الاختيار الأول"}],[{en:"K-truss, sub-divided truss (big panels 2a = 2.5–4 m — 3–4 m keeps a at 1.5–2 m — small panels a multiple of 4, so the ridge falls on a main vertical)",ar:"جمالون K، وجمالون مقسّم (باكيات كبيرة 2a = 2.5–4 م — و 3–4 م بتخلي a بين 1.5 و 2 م — وعدد البواكي الصغيرة من مضاعفات 4، علشان الـ Ridge تقع على قائم رئيسي)"},{en:"spans above about 34 m, or when the N-truss diagonals pass 60°",ar:"بحور فوق حوالي 34 م، أو لما أقطار جمالون N تعدّي 60°"}],[{en:"parallel-chord truss, a = 1.5–2 m",ar:"جمالون أوتاره متوازية، و a = 1.5–2 م"},{en:"spans up to about 20 m, flat roofs; on a pitched roof both chords rise to the ridge at the roof slope, so the depth stays constant",ar:"بحور لحد حوالي 20 م، أسقف مسطحة؛ وفي السقف المايل الوترين الاتنين بيطلعوا للـ Ridge بميل السقف، فالعمق بيفضل ثابت"}],[{en:"Fink (triangular) truss, h = 0; a = 1.5–2 m measured along the sloping chord",ar:"جمالون Fink (مثلث)، h = 0؛ و a = 1.5–2 م متقاسة بطول الوتر المايل"},{en:"spans below about 24 m with steep roofs",ar:"بحور أقل من حوالي 24 م بأسقف مايلة أوي"}]],caption:{en:"In a sub-divided truss the gable columns and the longitudinal bracing sit at multiples of 2a. Which members are pulled or pushed follows from the truss as a deep beam — see the buckling-length episode.",ar:"في الجمالون المقسّم أعمدة الواجهة والشكالات الطولية بتقع على مضاعفات 2a. ومين مشدود ومين مضغوط بيطلع من الجمالون ككمرة عميقة — شوف حلقة طول الانبعاج."}},{t:"p",text:{en:"**Designing a sub-divided truss.** Unless a problem names the type, always try an N (or K) truss first, and switch to a sub-divided truss only when the N-truss diagonals pass 60°. Then size the **big panel 2a** — the panel of the lower chord between two main verticals — instead of a:",ar:"**تصميم الجمالون المقسّم.** إلا لو المسألة محددة النوع، جرّب دايمًا جمالون N (أو K) الأول، وماتروحش للجمالون المقسّم غير لما أقطار جمالون N تعدّي 60°. وساعتها صمّم **الباكية الكبيرة 2a** — باكية الوتر السفلي بين قائمين رئيسيين — بدل a:"}},{t:"steps",items:[{en:"$2a \\approx (H + h)/2$, within 2.5–4 m (3–4 m so that the purlin spacing a stays 1.5–2 m).",ar:"$2a \\approx (H + h)/2$، في حدود 2.5–4 م (3–4 م علشان المسافة بين المدادات a تفضل 1.5–2 م)."},{en:"Number of big panels $B/2a$, rounded to an **even** number, so that the small panels are divisible by 4 and the ridge falls on a main vertical; rounding to a multiple of 4 also puts a longitudinal-bracing line at the ridge.",ar:"عدد الباكيات الكبيرة $B/2a$، مقرّب لرقم **زوجي**، علشان البواكي الصغيرة تقبل القسمة على 4 والـ Ridge تقع على قائم رئيسي؛ ولو قرّبته لمضاعف 4 كمان، بيبقى فيه خط شكالات طولية عند الـ Ridge."},{en:"$2a = B/n$; check $\\tan^{-1}(h/2a) \\ge 30°$ and $\\tan^{-1}(H/2a) \\le 60°$ — 2a about between h and H.",ar:"$2a = B/n$؛ وراجع $\\tan^{-1}(h/2a) \\ge 30°$ و $\\tan^{-1}(H/2a) \\le 60°$ — يعني 2a تقريبًا بين h و H."},{en:"Longitudinal bracing and gable columns on the main verticals only — at multiples of 2a, usually every 4a — never on the short sub-verticals.",ar:"الشكالات الطولية وأعمدة الواجهة على القوائم الرئيسية بس — على مضاعفات 2a، والمعتاد كل 4a — وعمرها ما تتحط على القوائم الفرعية القصيرة."}]},{t:"p",text:{en:"**Example — a 45 m span.** $H = 45/12 = 3.75$ m. At 10:1, $h = 3.75 - 2.25 = 1.50$ m. N-truss first: $a = 2.0$ gives $45/2 = 22.5 \\to 24$ panels of 1.875 m, and $\\tan^{-1}(3.75/1.875) = 63.4° > 60°$ ✗ → sub-divided. But with h = 1.50 m the big panel would have to stay below $\\sqrt3\\times1.50 = 2.60$ m, shorter than the 3.0 m that $a \\ge 1.5$ m needs — so take the flatter **20:1** (on spans this wide it is often taken from the start): $h = 3.75 - 1.125 = 2.625$ m. Then $2a \\approx (3.75 + 2.625)/2 = 3.19$ m, $45/3.19 = 14.1$ → **12 big panels** (a multiple of 4), $2a = 3.75$ m and $a = 1.875$ m; angles $\\tan^{-1}(2.625/3.75) = 35.0°$ and $\\tan^{-1}(3.75/3.75) = 45.0°$ ✓. Longitudinal bracing every $4a = 7.5$ m: five lines at 7.5, 15, 22.5, 30 and 37.5 m, with depths $2.625 + 7.5/20 = 3.00$ m, 3.375 m and 3.75 m at the ridge.",ar:"**مثال — بحر 45 م.** $H = 45/12 = 3.75$ م. عند 10:1، $h = 3.75 - 2.25 = 1.50$ م. جمالون N الأول: $a = 2.0$ بتدّي $45/2 = 22.5 \\to 24$ باكية كل واحدة 1.875 م، و $\\tan^{-1}(3.75/1.875) = 63.4° > 60°$ ✗ ← مقسّم. بس مع h = 1.50 م الباكية الكبيرة لازم تفضل أقل من $\\sqrt3\\times1.50 = 2.60$ م، أقصر من الـ 3.0 م اللي $a \\ge 1.5$ م محتاجاها — يبقى خد الميل الأفلطح **20:1** (وفي البحور العريضة دي كتير بيتاخد من الأول): $h = 3.75 - 1.125 = 2.625$ م. وبعدين $2a \\approx (3.75 + 2.625)/2 = 3.19$ م، و $45/3.19 = 14.1$ ← **12 باكية كبيرة** (مضاعف 4)، و $2a = 3.75$ م و $a = 1.875$ م؛ والزوايا $\\tan^{-1}(2.625/3.75) = 35.0°$ و $\\tan^{-1}(3.75/3.75) = 45.0°$ ✓. شكالات طولية كل $4a = 7.5$ م: خمس خطوط عند 7.5 و 15 و 22.5 و 30 و 37.5 م، وأعماقها $2.625 + 7.5/20 = 3.00$ م، و 3.375 م، و 3.75 م عند الـ Ridge."}},{t:"note",tone:"tip",text:{en:"**Which member is pulled?** Read the truss as a deep simply supported beam: under gravity its upper chord is compressed and its lower chord pulled; a diagonal that slopes down towards mid-span, like the moment diagram, is pulled, one sloping the other way is pushed; over a cantilever every sign reverses. Lay the long diagonals out in tension — steel works best pulled. The verticals follow no such rule: only a joint equilibrium tells their sign. Forces are written + for tension and − for compression (worked out in the buckling-length episode).",ar:"**مين المشدود؟** اقرا الجمالون ككمرة بسيطة عميقة: تحت الأحمال الرأسية وتره العلوي مضغوط والسفلي مشدود؛ والقطري اللي نازل ناحية النص، زي منحنى العزوم، مشدود، واللي مايل عكسه مضغوط؛ وعلى الكابولي كل الإشارات بتنعكس. رتّب الأقطار الطويلة علشان تشتغل شد — الحديد بيشتغل أحسن وهو مشدود. أما القوائم فمالهاش قاعدة: اتزان العقدة بس هو اللي بيقول إشارتها. والقوى بتتكتب + للشد و − للضغط (متحلولة في حلقة طول الانبعاج)."}},{t:"lab",lab:"shed",height:500,props:{preset:"layout",missions:o,defaultTab:"steps"},caption:{en:"The 26 m example in the layout designer: Solution shows the eight steps with your numbers; Results flags every broken rule.",ar:"مثال الـ 26 م في مصمم التخطيط: الحل بيوري التمن خطوات بأرقامك؛ والنتائج بتعلّم على أي قاعدة مكسورة."}},{t:"quiz",q:{kind:"num",q:{en:"A 30 m span with H = 30/12. The slope 10:1 fails; at 20:1, h = ? (m)",ar:"بحر 30 م و H = 30/12. الميل 10:1 مش نافع؛ عند 20:1، h = ؟ (م)"},answer:1.75,tol:.003,unit:"m",explain:{en:"$H = 2.50$; 10:1 gives $2.50 - 1.50 = 1.00 < 1.25$; 20:1 gives $h = 2.50 - 15/20 = 1.75$ m ✓.",ar:"$H = 2.50$؛ الـ 10:1 بتدّي $2.50 - 1.50 = 1.00 < 1.25$؛ والـ 20:1 بتدّي $h = 2.50 - 15/20 = 1.75$ م ✓."}}}]},{id:"bracing",title:{en:"The three bracing systems",ar:"أنظمة الشكالات التلاتة"},blocks:[{t:"p",text:{en:"**Roof (horizontal) bracing** — X members in the plane of the upper chords, in **both end bays**, turning the end bay into a horizontal truss that collects the gable wind. Braced bays are never more than **25–30 m** apart: if the clear distance between the first and the last one is larger, add one (or more) in the middle. Its diagonals stay at 30°–60°, and it is laid slope by slope: it does not run across the ridge fold (nor across a change of roof level).",ar:"**شكالات السقف (الأفقية)** — أعضاء X في مستوى الأوتار العلوية، في **الباكيتين الطرفيتين**، بتخلي الباكية الطرفية جمالون أفقي بيلم رياح الواجهة. باكيات الشكالات عمرها ما تبعد عن بعض أكتر من **25–30 م**: لو المسافة الصافية بين أول واحدة وآخر واحدة أكبر، زوّد واحدة (أو أكتر) في النص. أقطارها بين 30° و 60°، وبتتعمل ميل ميل: مبتعدّيش على كسرة الـ Ridge (ولا على تغيير منسوب السقف)."}},{t:"p",text:{en:"**Why roof bracing, when the walls are braced?** The wind on a gable wall reaches the roof over the whole width of the building, not only at the eaves. Without a horizontal truss to collect it, it would bend the end truss about its weak axis — out of its plane — and the truss would bow sideways between its two columns. The vertical bracing holds only the eaves; the roof bracing carries the load from the middle of the width out to them.",ar:"**ليه شكالات السقف، لو الحوائط عليها شكالات؟** رياح حائط الواجهة بتوصل للسقف على عرض المبنى كله، مش عند الـ Eaves بس. من غير جمالون أفقي يلمّها، كانت هتحني الجمالون الطرفي حوالين محوره الضعيف — خارج مستواه — والجمالون كان هيتقوّس جنب بين عموديه. الشكالات الرأسية ماسكة الـ Eaves بس؛ وشكالات السقف هي اللي بتوصّل الحمل من نص العرض ليهم."}},{t:"p",text:{en:"**Vertical bracing** — X members between the columns of the side walls, **in the same bays** as the roof bracing: they receive its reactions at the eaves and take them down to the footings (with the braking of a crane). When the clear height is **6 m or more** (6 m itself included), a horizontal **strut** at mid-height splits the wall into two tiers and halves the columns' buckling length along the building; it runs continuously along the wall, through the crossing of the X. Beyond 12 m one more tier is added for every further 6 m.",ar:"**الشكالات الرأسية** — أعضاء X بين أعمدة الحوائط الجانبية، **في نفس الباكيات** اللي فيها شكالات السقف: بتستلم ردود أفعالها عند الـ Eaves وبتنزّلها للقواعد (ومعاها فرامل الونش). لما الارتفاع الصافي يبقى **6 م أو أكتر** (والـ 6 م نفسها داخلة)، **عضو أفقي** في نص الارتفاع بيقسم الحائط لدورين وبيقسم طول انبعاج الأعمدة بطول المبنى على اتنين؛ وبيمشي مستمر بطول الحائط، ويعدّي من نقطة تقاطع الـ X. وفوق 12 م بيتزوّد دور مع كل 6 م زيادة."}},{t:"p",text:{en:"**Two zones in the wall.** The wall of a braced bay has two parts. Between the lower-chord level and the upper chord — the **truss-depth zone** h, right under the roof bracing — the bracing is a small vertical truss: a **V** (two diagonals from the top corners down to the middle), an inverted V, or a **W** (two V's side by side), whichever keeps 30°–60°. Below it, over the **clear height**, an **X**. A V over a bay S needs $h \\ge \\dfrac{S}{2}\\tan30° = \\dfrac{S}{2\\sqrt3}$; a W halves the run of each diagonal. **Example** — h = 1.25 m, S = 5 m, clear height 6 m: a V lies at $\\tan^{-1}(1.25/2.5) = 26.6°$ ✗ (it would need $h \\ge 5/(2\\sqrt3) = 1.44$ m), a W at $\\tan^{-1}(1.25/1.25) = 45°$ ✓, and the X below at $\\tan^{-1}(6/5) = 50.2°$ ✓, with the strut at 3 m through its crossing (two tiers of X would lie at $\\tan^{-1}(3/5) = 31.0°$, also acceptable).",ar:"**منطقتين في الحائط.** حائط الباكية اللي فيها شكالات ليه جزئين. بين منسوب الوتر السفلي والوتر العلوي — **منطقة عمق الجمالون** h، تحت شكالات السقف على طول — الشكالات بتبقى جمالون رأسي صغير: **V** (قطرين من الركنين اللي فوق نازلين للنص)، أو V مقلوبة، أو **W** (اتنين V جنب بعض)، أيهم يحافظ على 30°–60°. وتحتها، على **الارتفاع الصافي**، **X**. الـ V على باكية S محتاجة $h \\ge \\dfrac{S}{2}\\tan30° = \\dfrac{S}{2\\sqrt3}$؛ والـ W بتقسم مسافة كل قطري على اتنين. **مثال** — h = 1.25 م، و S = 5 م، وارتفاع صافي 6 م: الـ V زاويتها $\\tan^{-1}(1.25/2.5) = 26.6°$ ✗ (كانت محتاجة $h \\ge 5/(2\\sqrt3) = 1.44$ م)، والـ W زاويتها $\\tan^{-1}(1.25/1.25) = 45°$ ✓، والـ X اللي تحت $\\tan^{-1}(6/5) = 50.2°$ ✓، والعضو الأفقي عند 3 م بيعدّي من تقاطعها (ودورين X كانوا هيبقوا عند $\\tan^{-1}(3/5) = 31.0°$، ومقبولين كمان)."}},{t:"p",text:{en:"**The strut runs the whole wall.** When the clear height needs it, the mid-height member is continuous along the wall through **every** bay: it holds every column at mid-height, not only the columns of the braced bay. In a braced bay it either passes through the crossing of one full-height X, or the bay gets one X per tier, as the lab draws it — choose whichever keeps the diagonals within 30°–60°. The rule already applies at exactly 6 m: the strut then sits at 3 m.",ar:"**العضو الأفقي ماشي بطول الحائط كله.** لما الارتفاع الصافي يحتاجه، العضو اللي في نص الارتفاع بيبقى مستمر بطول الحائط في **كل** الباكيات: بيمسك كل الأعمدة من نصها، مش أعمدة باكية الشكالات بس. وفي الباكية اللي فيها شكالات يا إما بيعدّي من نقطة تقاطع X واحدة على الارتفاع كله، يا إما الباكية بتاخد X لكل دور، زي ما المعمل راسمها — اختار اللي يخلي الأقطار بين 30° و 60°. والقاعدة شغالة من عند 6 م بالظبط: العضو الأفقي ساعتها بيبقى عند 3 م."}},{t:"p",text:{en:"**Longitudinal bracing** — a vertical truss between neighbouring trusses on one line: a tie along the lower chords with V diagonals in the braced bays, the purlin above acting as its upper chord. Its lines are **at most 8 m apart**, preferably on the gable-column lines (a 16–24 m span needs 2 lines); its depth is the truss depth on its line, $d = h + x/Z$. It holds the lower chord out of plane (the chord can be compressed under wind uplift) and ties the trusses together. With **reinforced-concrete columns** the vertical bracing can go (the concrete columns and frames carry the horizontal loads), but the roof and the longitudinal bracing stay.",ar:"**الشكالات الطولية** — جمالون رأسي بين الجمالونات الجيران على خط واحد: شداد بطول الأوتار السفلية وأقطار V في باكيات الشكالات، والمداد اللي فوق شغال كوتره العلوي. خطوطها **مش أبعد من 8 م** عن بعض، ويفضل على خطوط أعمدة الواجهة (بحر 16–24 م محتاج خطين)؛ وعمقها هو عمق الجمالون على خطها، $d = h + x/Z$. بتمسك الوتر السفلي خارج المستوى (الوتر ممكن يتضغط تحت رفع الرياح) وبتربط الجمالونات ببعض. ولو **الأعمدة خرسانة مسلحة** الشكالات الرأسية ممكن تتشال (الأعمدة والإطارات الخرسانية بتشيل الأحمال الأفقية)، لكن شكالات السقف والطولية بيفضلوا."}},{t:"p",text:{en:"**The longitudinal bracing as a truss.** Together with the purlins it ties all the trusses into one **space truss**. Its elevation is a vertical truss: the purlin above, a continuous tie along the lower chords below, a vertical at every truss and, in the braced bays, a V or a W chosen by the same 30°–60° check as the wall — a single V needs a depth of at least $S/(2\\sqrt3)$, which is 1.73 m in a 6 m bay.",ar:"**الشكالات الطولية كجمالون.** هي والمدادات بيربطوا كل الجمالونات في **جمالون فراغي (Space truss)** واحد. واجهتها جمالون رأسي: المداد فوق، وشداد مستمر بطول الأوتار السفلية تحت، وقائم عند كل جمالون، وفي باكيات الشكالات V أو W بتتختار بنفس مراجعة الـ 30°–60° بتاعة الحائط — الـ V الواحدة محتاجة عمق على الأقل $S/(2\\sqrt3)$، يعني 1.73 م في باكية 6 م."}},{t:"p",text:{en:"**On reinforced-concrete columns.** Assume RC columns of about 300 × 600 mm (the gable columns too), RC wall beams of about 250 × 600 mm at the column tops and at an intermediate level, and brick panels between them. Columns and beams form a frame in the wall plane, so the X under the eaves goes. Keep, however, the V or W of the truss-depth zone in the braced bays — it brings the roof-bracing reactions down from the upper chord to the concrete — and keep the roof and the longitudinal bracing.",ar:"**على أعمدة خرسانة مسلحة.** افترض أعمدة خرسانية حوالي 300 × 600 مم (وأعمدة الواجهة كمان)، وكمرات حوائط خرسانية حوالي 250 × 600 مم عند رؤوس الأعمدة وعند منسوب في النص، وحوائط طوب بينهم. الأعمدة والكمرات بيعملوا إطار في مستوى الحائط، فالـ X اللي تحت الـ Eaves بتتشال. لكن سيب الـ V أو الـ W بتاعة منطقة عمق الجمالون في باكيات الشكالات — دي اللي بتنزّل ردود أفعال شكالات السقف من الوتر العلوي للخرسانة — وسيب شكالات السقف والشكالات الطولية."}},{t:"p",text:{en:"**Example — the 26 × 55 m shed, clear height 7.5 m** (11 bays of 5 m). The end bays 1 and 11 are $9\\times5 = 45$ m apart > 30 m → add bay 6: two gaps of $4\\times5 = 20$ m ✓. Vertical bracing in bays 1, 6 and 11, with a strut at 3.75 m because 7.5 m ≥ 6 m. Longitudinal bracing: 26 m needs 3 lines, at 7.43, 13.00 and 18.57 m (panel points 4, 7, 10), 7.43 / 5.57 / 5.57 / 7.43 m apart; depths $1.50 + 7.43/20 = 1.87$ m, 2.15 m at the ridge.",ar:"**مثال — الهنجر 26 × 55 م بارتفاع صافي 7.5 م** (11 باكية كل واحدة 5 م). الباكيتين الطرفيتين 1 و 11 بينهم $9\\times5 = 45$ م > 30 م ← زوّد الباكية 6: مسافتين كل واحدة $4\\times5 = 20$ م ✓. شكالات رأسية في الباكيات 1 و 6 و 11، بعضو أفقي عند 3.75 م لأن 7.5 م ≥ 6 م. شكالات طولية: الـ 26 م محتاجة 3 خطوط، عند 7.43 و 13.00 و 18.57 م (عقد 4 و 7 و 10)، والمسافات 7.43 / 5.57 / 5.57 / 7.43 م؛ والأعماق $1.50 + 7.43/20 = 1.87$ م، و 2.15 م عند الـ Ridge."}},{t:"p",text:{en:"**Patterns for the roof bracing.** Any arrangement works as long as each diagonal stays at 30°–60°: X's over 2, 3 or 4 panels, a mix of them with a half-X, or single diagonals in a zig-zag. Each half-width, eave to ridge, is braced on its own. With the bay S and an X spanning a width w of the truss (a whole number of panels):",ar:"**أشكال شكالات السقف.** أي ترتيب ينفع طول ما كل قطري بين 30° و 60°: X على باكيتين أو تلاتة أو أربعة، أو خليط منهم مع نص X، أو أقطار مفردة متعرجة (Zig-zag). وكل نص عرض، من الـ Eaves للـ Ridge، بيتعمل لوحده. ولو الباكية S والـ X مغطية عرض w من الجمالون (عدد صحيح من البواكي):"}},{t:"eq",tex:["30° \\le \\tan^{-1}\\dfrac{S}{w} \\le 60° \\quad\\Leftrightarrow\\quad \\dfrac{S}{\\sqrt3} \\le w \\le \\sqrt3\\,S"],caption:{en:"S = truss spacing (the braced bay); w = width of one X measured along the truss. Aim for braced bays at most 25 m apart; 30 m is the limit.",ar:"S = المسافة بين الجمالونات (باكية الشكالات)؛ و w = عرض الـ X الواحدة متقاس بطول الجمالون. حاول باكيات الشكالات متبعدش عن بعض أكتر من 25 م؛ والـ 30 م هي الحد."}},{t:"p",text:{en:"**The 26 × 55 m shed, pattern by pattern.** Each 13 m half holds 7 panels of 1.857 m, and $w$ must lie between $5/\\sqrt3 = 2.89$ m and $\\sqrt3\\times5 = 8.66$ m. A single panel is too narrow ($\\tan^{-1}(5/1.857) = 69.6°$ ✗), but X's over **4 + 3 panels** (7.43 m and 5.57 m) give $33.9°$ and $41.9°$ ✓. Their nodes fall on joints 4 and 7 — at 7.43 m and at the ridge — and it pays to put the **gable columns** and the longitudinal-bracing lines exactly on such nodes: the wind then passes from each gable column straight into a node of the roof bracing (on the nodes, gable columns 4–8 m apart are accepted). In the walls h = 1.50 m: a V just passes at $\\tan^{-1}(1.50/2.5) = 31.0°$, a W at $\\tan^{-1}(1.50/1.25) = 50.2°$ is more comfortable; below, one full-height X lies at $\\tan^{-1}(7.5/5) = 56.3°$ and two tiers at $\\tan^{-1}(3.75/5) = 36.9°$ — both acceptable, with the strut at 3.75 m running the whole wall. The longitudinal elevations, 1.87 m and 2.15 m deep, take a single V ($36.8°$ and $40.7°$).",ar:"**الهنجر 26 × 55 م، شكل شكل.** كل نص 13 م فيه 7 بواكي كل واحدة 1.857 م، و $w$ لازم تبقى بين $5/\\sqrt3 = 2.89$ م و $\\sqrt3\\times5 = 8.66$ م. الباكية الواحدة ضيقة أوي ($\\tan^{-1}(5/1.857) = 69.6°$ ✗)، لكن X على **4 + 3 بواكي** (7.43 م و 5.57 م) بتدّي $33.9°$ و $41.9°$ ✓. عقدها بتقع على العقد 4 و 7 — عند 7.43 م وعند الـ Ridge — والأحسن تحط **أعمدة الواجهة** وخطوط الشكالات الطولية على العقد دي بالظبط: الرياح ساعتها بتعدّي من كل عمود واجهة لعقدة في شكالات السقف على طول (وعلى العقد مقبول أعمدة الواجهة تبقى كل 4–8 م). وفي الحوائط h = 1.50 م: الـ V بتعدّي بالعافية عند $\\tan^{-1}(1.50/2.5) = 31.0°$، والـ W عند $\\tan^{-1}(1.50/1.25) = 50.2°$ أريح؛ وتحت، X واحدة على الارتفاع كله زاويتها $\\tan^{-1}(7.5/5) = 56.3°$ ودورين $\\tan^{-1}(3.75/5) = 36.9°$ — الاتنين مقبولين، والعضو الأفقي عند 3.75 م ماشي بطول الحائط كله. وواجهات الشكالات الطولية، بعمق 1.87 م و 2.15 م، بتاخد V واحدة ($36.8°$ و $40.7°$)."}},{t:"lab",lab:"shed",height:500,props:{preset:"default",missions:h,defaultTab:"inputs"},caption:{en:"An 18 × 36 m shed, clear height 6.5 m: change the length and the height, and switch the bracing layers off in the list.",ar:"هنجر 18 × 36 م بارتفاع صافي 6.5 م: غيّر الطول والارتفاع، واقفل طبقات الشكالات من القايمة."}},{t:"quiz",q:{kind:"num",q:{en:"A shed 60 m long, 10 bays of 6 m, roof bracing in both end bays only: the clear distance between them (m)?",ar:"هنجر طوله 60 م، 10 باكيات كل واحدة 6 م، وشكالات السقف في الباكيتين الطرفيتين بس: المسافة الصافية بينهم (م)؟"},answer:48,tol:.001,unit:"m",explain:{en:"$8\\times6 = 48$ m > 25–30 m: a middle braced bay is needed (bay 6 leaves 24 and 18 m).",ar:"$8\\times6 = 48$ م > 25–30 م: لازم باكية شكالات في النص (الباكية 6 بتسيب 24 و 18 م)."}}}]},{id:"walls",title:{en:"Walls, gables, drawings and car sheds",ar:"الحوائط والواجهات واللوحات ومظلات العربيات"},blocks:[{t:"p",text:{en:"**Side girts** run between the columns. The lowest sits on top of a **brick dado** 2–3 m high, the next above a **window band** of 1–1.5 m, and the rest are spaced **1.5–2 m** up to the eaves. **End walls** get **gable columns** 5–8 m apart — preferably on the longitudinal-bracing lines — carrying **end girts** at the same levels; each gable column spans from its footing to the roof bracing.",ar:"**الـ Girts الجانبية** ماشية بين الأعمدة. أوطى واحد فوق **حائط طوب** ارتفاعه 2–3 م، واللي بعده فوق **شريط شبابيك** 1–1.5 م، والباقي كل **1.5–2 م** لحد الـ Eaves. و**الحوائط الطرفية** ليها **أعمدة واجهة** كل 5–8 م — ويفضل على خطوط الشكالات الطولية — شايلة **Girts طرفية** على نفس المناسيب؛ وكل عمود واجهة بحره من قاعدته لشكالات السقف."}},{t:"p",text:{en:"**Turn the gable columns the other way.** A main column bends in the plane of its truss, so its web lies across the building. A gable column is loaded by the wind on the end wall, which pushes it **along** the building — so its web, its strong axis, is turned along the building, at right angles to the end wall. On a plan the gable columns are therefore drawn rotated 90° from the main columns.",ar:"**لف أعمدة الواجهة الناحية التانية.** العمود الرئيسي بيتحني في مستوى الجمالون بتاعه، فعصبه بعرض المبنى. لكن عمود الواجهة شايل رياح الحائط الطرفي، اللي بتزقّه **بطول** المبنى — فعصبه، محوره القوي، بيتلف بطول المبنى، عمودي على الحائط الطرفي. وعلشان كده في المسقط أعمدة الواجهة بتترسم ملفوفة 90° عن الأعمدة الرئيسية."}},{t:"p",text:{en:"**Example.** Clear height 7.5 m, brick to 2.5 m, windows to 3.75 m: the remaining 3.75 m take two spaces of 1.875 m, so the girts sit at 2.5, 3.75, 5.625 and 7.5 m (the truss depth above is clad between its chords).",ar:"**مثال.** ارتفاع صافي 7.5 م، الطوب لحد 2.5 م، والشبابيك لحد 3.75 م: الـ 3.75 م الباقيين بياخدوا مسافتين كل واحدة 1.875 م، فالـ Girts عند 2.5 و 3.75 و 5.625 و 7.5 م (وعمق الجمالون اللي فوق بيتكسي بين أوتاره)."}},{t:"p",text:{en:"**Openings and corners.** A window is a band of side wall left without sheets, framed by the girts at its sill and head. A door in an end wall is one bay between two gable columns left open below a girt that acts as its head. At a corner the column carries the side girts on one face and the end girts on the other, at the same levels; the wall sheets are fixed outside the girts with their corrugations **vertical**, so that rain runs straight down them, while on the roof the corrugations run down the slope, across the purlins.",ar:"**الفتحات والأركان.** الشباك شريط من الحائط الجانبي متساب من غير صاج، محدود بالـ Girts اللي عند جلسته وعتبته. والباب في الحائط الطرفي باكية بين عمودين واجهة متسابة مفتوحة تحت Girt شغال كعتبة ليه. وعند الركن العمود بيشيل الـ Girts الجانبية على وش والـ Girts الطرفية على الوش التاني، على نفس المناسيب؛ وصاج الحوائط بيتركب برّه الـ Girts وتموجاته **رأسية**، علشان المطر ينزل عليه على طول، أما في السقف فالتموجات ماشية مع الميل، بعرض المدادات."}},{t:"p",text:{en:"**Drawings** are made at 1:100 (or 1:200): 1 m on site is 1 cm on paper, so an HEB 300 column is a 3 mm square, a UPN 140 purlin a 1.4 mm line and a 26 m truss 26 cm long. A layout set has five drawings: the plan (trusses, purlins, roof bracing, columns), the main-system section, the end gable, the vertical bracing and the longitudinal bracing.",ar:"**اللوحات** بتترسم بمقياس 1:100 (أو 1:200): المتر في الموقع سنتيمتر على الورق، فعمود HEB 300 مربع 3 مم، ومداد UPN 140 خط 1.4 مم، وجمالون 26 م طوله 26 سم. ومجموعة لوحات التخطيط فيها خمس لوحات: المسقط (الجمالونات والمدادات وشكالات السقف والأعمدة)، وقطاع النظام الرئيسي، والواجهة الطرفية، والشكالات الرأسية، والشكالات الطولية."}},{t:"note",tone:"warn",text:{en:"**Car sheds (cantilever trusses, depth at the column span/(5–8)):** no end-gable system is needed (the sides are open: no gable columns, no side or end girts), but put a longitudinal-bracing line **at the tip** of the cantilever, keep the lines close, and reverse the diagonals of the cantilever so that they work in tension — over a cantilever the lower chord is the compressed one. The next section lays these trusses out.",ar:"**مظلات العربيات (جمالونات كابولي، عمقها عند العمود البحر/(5–8)):** مش محتاجة نظام واجهة (الجوانب مفتوحة: لا أعمدة واجهة ولا Girts جانبية ولا طرفية)، لكن حط خط شكالات طولية **عند طرف** الكابولي، وقرّب الخطوط، واعكس أقطار الكابولي علشان تشتغل شد — على الكابولي الوتر السفلي هو اللي مضغوط. والجزء الجاي بيخطّط الجمالونات دي."}},{t:"quiz",q:{kind:"num",q:{en:"Brick up to 3 m, a 1.5 m window band, clear height 8 m, girts at most 2 m apart: how many equal spaces above the window?",ar:"طوب لحد 3 م، وشريط شبابيك 1.5 م، وارتفاع صافي 8 م، والـ Girts كل 2 م بالكتير: كام مسافة متساوية فوق الشباك؟"},answer:2,tol:.001,explain:{en:"$8 - 4.5 = 3.5$ m; $3.5/2 = 1.75$ → 2 spaces of 1.75 m (girts at 3.0, 4.5, 6.25 and 8.0 m).",ar:"$8 - 4.5 = 3.5$ م؛ و $3.5/2 = 1.75$ ← مسافتين كل واحدة 1.75 م (الـ Girts عند 3.0 و 4.5 و 6.25 و 8.0 م)."}}}]},{id:"cantilever",title:{en:"Overhangs and car sheds: the truss as a cantilever",ar:"الكوابيل ومظلات العربيات: الجمالون ككابولي"},blocks:[{t:"p",text:{en:"**A factory with a canopy.** When a car shed runs along one long wall, the truss simply continues past the wall column as a cantilever. The span that sets H is still the distance **between the columns**. The upper chord continues at the roof slope to the tip while the lower chord stays level, so the truss gets shallower towards the tip. Over the cantilever the moment is hogging — upper chord pulled, lower chord compressed — so the diagonals are turned the other way to stay in tension, and a longitudinal-bracing line always goes at the tip.",ar:"**مصنع بمظلة.** لما مظلة عربيات تمشي بطول حائط طويل، الجمالون ببساطة بيكمّل بعد عمود الحائط ككابولي. والبحر اللي بيحدد H لسه هو المسافة **بين الأعمدة**. الوتر العلوي بيكمّل بميل السقف لحد الطرف والوتر السفلي بيفضل أفقي، فالجمالون بيقل عمقه ناحية الطرف. وعلى الكابولي العزم سالب (الشد فوق) — الوتر العلوي مشدود والسفلي مضغوط — فالأقطار بتتعكس علشان تفضل شغالة شد، وخط شكالات طولية لازم يبقى عند الطرف."}},{t:"eq",tex:["d_{tip} = h - \\dfrac{c}{Z}"],caption:{en:"h = depth at the wall column, c = length of the cantilever, Z:1 = roof slope.",ar:"h = العمق عند عمود الحائط، و c = طول الكابولي، و Z:1 = ميل السقف."}},{t:"p",text:{en:"**Example.** The 19 m factory of the procedure below (h = 1.25 m at 20:1) with a 5 m canopy: $d_{tip} = 1.25 - 5/20 = 1.00$ m. Three panels of $5/3 = 1.667$ m keep the diagonals at $\\tan^{-1}(1.00/1.667) = 31.0°$ and $\\tan^{-1}(1.25/1.667) = 36.9°$ ✓, and H is still found from the 19 m span.",ar:"**مثال.** مصنع الـ 19 م اللي في الخطوات تحت (h = 1.25 م بميل 20:1) بمظلة 5 م: $d_{tip} = 1.25 - 5/20 = 1.00$ م. تلات بواكي كل واحدة $5/3 = 1.667$ م بتخلي الأقطار عند $\\tan^{-1}(1.00/1.667) = 31.0°$ و $\\tan^{-1}(1.25/1.667) = 36.9°$ ✓، و H لسه بتتحسب من بحر الـ 19 م."}},{t:"p",text:{en:"**A car shed on one line of columns.** The main system is a cantilever truss $H = c/(5\\sim8)$ deep at the column — take the deeper end. It may taper towards the tip (as in the systems episode) or keep the **same depth** all along: two parallel chords, the whole truss tilted at the roof slope. Choose the panel close to H so that the diagonals sit near 45°; the number of panels **need not be even**, since there is no ridge. And leave out what open sides do not need: no gable columns, no side girts, no end girts. **Example — a 10 m car shed:** $H = 10/5 = 2.0$ m ($c/8$ would give 1.25 m), kept constant; five panels of 2.0 m — an odd number, accepted — with diagonals at $\\tan^{-1}(2.0/2.0) = 45°$.",ar:"**مظلة عربيات على خط أعمدة واحد.** النظام الرئيسي جمالون كابولي عمقه عند العمود $H = c/(5\\sim8)$ — خد الناحية الأعمق. ممكن يقل عمقه ناحية الطرف (زي حلقة الأنظمة) أو يفضل **بنفس العمق** على طوله: وترين متوازيين، والجمالون كله مايل بميل السقف. اختار الباكية قريبة من H علشان الأقطار تبقى حوالين 45°؛ وعدد البواكي **مش لازم يبقى زوجي**، لأن مفيش Ridge. وشيل اللي الجوانب المفتوحة مش محتاجاه: لا أعمدة واجهة، ولا Girts جانبية، ولا Girts طرفية. **مثال — مظلة 10 م:** $H = 10/5 = 2.0$ م (الـ $c/8$ كانت هتدّي 1.25 م)، ثابت على الطول؛ خمس بواكي كل واحدة 2.0 م — عدد فردي، ومقبول — والأقطار عند $\\tan^{-1}(2.0/2.0) = 45°$."}},{t:"p",text:{en:"**Longitudinal bracing on a cantilever:** always a line at the tip, the lines closer together than in a span, and the reversed diagonals in mind. On the 10 m shed, lines at 2, 6 and 10 m or lines at 4, 8 and 10 m both keep every gap at 4 m or less and both are correct; they differ in the buckling length they leave to the compressed lower chord, which the buckling-length episode works out.",ar:"**الشكالات الطولية على الكابولي:** دايمًا خط عند الطرف، والخطوط أقرب لبعض من البحر العادي، وخلي بالك من الأقطار المعكوسة. في مظلة الـ 10 م، خطوط عند 2 و 6 و 10 م أو خطوط عند 4 و 8 و 10 م الاتنين بيخلّوا كل مسافة 4 م أو أقل والاتنين صح؛ والفرق بينهم في طول الانبعاج اللي بيسيبوه للوتر السفلي المضغوط، وده متحلول في حلقة طول الانبعاج."}},{t:"p",text:{en:"**Two cantilevers at two levels.** A shed for cars and trucks can carry a low truss on one side of a column line and a high one on the other. A tapered truss must still keep 30° at its tip, $d_{tip} \\ge a\\tan30°$, so its depth at the column is at least $a\\tan30° + c/Z$ — here this, not $c/(5\\sim8)$, sets the depth. **Example:** cars on a 5 m arm with a 3.2 m clear height, trucks on an 8 m arm with a 6.0 m clear height, both falling 1:10 outward. Car truss: three panels of 1.667 m need $d_{tip} \\ge 0.96$ m, so $d \\ge 0.96 + 0.5 = 1.46$ → **1.6 m** at the column (rounded up with a margin) and 1.1 m at the tip ($33.4°$ and $43.8°$). Truck truss: five panels of 1.6 m need $d_{tip} \\ge 0.92$ m, $d \\ge 0.92 + 0.8 = 1.72$ → **1.8 m** at the column and 1.0 m at the tip ($32.0°$ and $48.4°$). On the column the car truss occupies 3.2–4.8 m and the truck truss starts 1.2 m higher, at 6.0 m; the vertical bracing of the column line gets a continuous horizontal member at every one of these levels (3.2, 4.8, 6.0 and 7.8 m) with X's, V's or W's between them by the same angle check. Two clear heights side by side, on interior columns, follow in the systems episode.",ar:"**كابولين على منسوبين.** مظلة للعربيات واللوريات ممكن تشيل جمالون واطي على ناحية من خط الأعمدة وجمالون عالي على الناحية التانية. الجمالون اللي عمقه بيقل لازم يحافظ على 30° عند طرفه، $d_{tip} \\ge a\\tan30°$، فعمقه عند العمود على الأقل $a\\tan30° + c/Z$ — وهنا ده، مش $c/(5\\sim8)$، اللي بيحدد العمق. **مثال:** العربيات على كابولي 5 م بارتفاع صافي 3.2 م، واللوريات على كابولي 8 م بارتفاع صافي 6.0 م، والاتنين نازلين 1:10 لبرّه. جمالون العربيات: تلات بواكي كل واحدة 1.667 م محتاجة $d_{tip} \\ge 0.96$ م، فـ $d \\ge 0.96 + 0.5 = 1.46$ ← **1.6 م** عند العمود (متقربة لفوق بهامش أمان) و 1.1 م عند الطرف ($33.4°$ و $43.8°$). جمالون اللوريات: خمس بواكي كل واحدة 1.6 م محتاجة $d_{tip} \\ge 0.92$ م، و $d \\ge 0.92 + 0.8 = 1.72$ ← **1.8 م** عند العمود و 1.0 م عند الطرف ($32.0°$ و $48.4°$). وعلى العمود جمالون العربيات واخد من 3.2 لـ 4.8 م وجمالون اللوريات بيبدأ أعلى منه بـ 1.2 م، عند 6.0 م؛ والشكالات الرأسية بتاعة خط الأعمدة بتاخد عضو أفقي مستمر عند كل منسوب من دول (3.2 و 4.8 و 6.0 و 7.8 م) وبينهم X أو V أو W بنفس مراجعة الزوايا. والارتفاعين الصافيين جنب بعض، على أعمدة وسطية، جايين في حلقة الأنظمة."}},{t:"quiz",q:{kind:"num",q:{en:"A factory truss with h = 1.25 m at the wall column and a 20:1 roof continues 6 m as a car-shed cantilever. Depth at the tip (m)?",ar:"جمالون مصنع عمقه h = 1.25 م عند عمود الحائط وميل سقفه 20:1 بيكمّل 6 م ككابولي لمظلة عربيات. العمق عند الطرف (م)؟"},answer:.95,tol:.005,unit:"m",explain:{en:"The upper chord keeps its slope and the lower chord stays level: $d_{tip} = 1.25 - 6/20 = 0.95$ m.",ar:"الوتر العلوي بيكمّل بميله والسفلي بيفضل أفقي: $d_{tip} = 1.25 - 6/20 = 0.95$ م."}}}]},{id:"procedure",title:{en:"The eight layout steps, on a whole factory",ar:"خطوات التخطيط التمانية على مصنع كامل"},blocks:[{t:"steps",items:[{en:"Truss type — start with an N (or K) truss spanning the short side.",ar:"نوع الجمالون — ابدأ بجمالون N (أو K) على الضلع القصير."},{en:"Depth at mid-span H = span/(12–16).",ar:"العمق في النص H = البحر/(12–16)."},{en:"Slope and h ≥ 1.25 m at the column (10:1, then 20:1, else h = 1.25 m and a larger H — or keep H and a flatter slope, down to 40:1).",ar:"الميل و h ≥ 1.25 م عند العمود (10:1، وبعدين 20:1، وإلا h = 1.25 م و H أكبر — أو سيب H وخد ميل أفلطح، لحد 40:1)."},{en:"Panels a ≈ (H + h)/2 — between h and H — 1.5–2 m, an even number; diagonals at 30°–60° (if not, a sub-divided truss).",ar:"البواكي a ≈ (H + h)/2 — بين h و H — من 1.5 لـ 2 م، عدد زوجي؛ والأقطار بين 30° و 60° (وإلا، جمالون مقسّم)."},{en:"Longitudinal bracing ≤ 8 m apart, on the gable-column lines.",ar:"شكالات طولية مش أبعد من 8 م، على خطوط أعمدة الواجهة."},{en:"Spacing S = L/(5–8), a whole number of bays.",ar:"المسافة S = L/(5–8)، عدد صحيح من الباكيات."},{en:"Vertical bracing: a strut at mid-height when the clear height is 6 m or more.",ar:"الشكالات الرأسية: عضو أفقي في نص الارتفاع لما الارتفاع الصافي يبقى 6 م أو أكتر."},{en:"Roof bracing in both end bays, another one whenever they are more than 25–30 m apart.",ar:"شكالات السقف في الباكيتين الطرفيتين، وواحدة زيادة كل ما يبعدوا أكتر من 25–30 م."}]},{t:"p",text:{en:"**Worked example — a factory 19 × 50 m, clear height 6 m.** (1) N-truss across 19 m. (2) $H = 19/12 = 1.58 \\to 1.55$ m. (3) 10:1 gives $h = 1.55 - 0.95 = 0.60$; 20:1 gives $1.55 - 0.475 = 1.075$ m, still below 1.25 → **h = 1.25 m, H = 1.25 + 0.475 = 1.725 m**. (4) $a \\approx 1.49$ → at least 1.5 m: $19/1.5 = 12.7$ → **12 panels, a = 1.583 m**; angles 38.3° and 47.5° ✓. (5) Two longitudinal lines at 6.33 and 12.67 m (6.33 m apart), 1.57 m deep. (6) $50/(5\\sim8)$ → **10 bays of 5 m**. (7) Clear height 6 m ≥ 6 m → a strut at **3.0 m**, continuous along both side walls through the crossing of the X (one X over the full height lies at $\\tan^{-1}(6/5) = 50.2°$). (8) Bays 1 and 10 are $8\\times5 = 40$ m apart → add **bay 6**: gaps of 20 m and 15 m. Gable columns on the longitudinal lines; girts at 2.5, 3.75, 4.875 and 6.0 m under the 1.25 m truss depth.",ar:"**مثال محلول — مصنع 19 × 50 م بارتفاع صافي 6 م.** (1) جمالون N على الـ 19 م. (2) $H = 19/12 = 1.58 \\to 1.55$ م. (3) الـ 10:1 بتدّي $h = 1.55 - 0.95 = 0.60$؛ والـ 20:1 بتدّي $1.55 - 0.475 = 1.075$ م، لسه أقل من 1.25 ← **h = 1.25 م و H = 1.25 + 0.475 = 1.725 م**. (4) $a \\approx 1.49$ ← على الأقل 1.5 م: $19/1.5 = 12.7$ ← **12 باكية، و a = 1.583 م**؛ والزوايا 38.3° و 47.5° ✓. (5) خطين شكالات طولية عند 6.33 و 12.67 م (بينهم 6.33 م)، عمقهم 1.57 م. (6) $50/(5\\sim8)$ ← **10 باكيات كل واحدة 5 م**. (7) الارتفاع الصافي 6 م ≥ 6 م ← عضو أفقي عند **3.0 م**، مستمر بطول الحائطين الجانبيين ويعدّي من تقاطع الـ X (والـ X الواحدة على الارتفاع كله زاويتها $\\tan^{-1}(6/5) = 50.2°$). (8) الباكيتين 1 و 10 بينهم $8\\times5 = 40$ م ← زوّد **الباكية 6**: مسافات 20 م و 15 م. أعمدة الواجهة على الخطوط الطولية؛ والـ Girts عند 2.5 و 3.75 و 4.875 و 6.0 م تحت عمق الجمالون 1.25 م."}},{t:"lab",lab:"shed",height:500,props:{preset:"layout",missions:l,defaultTab:"inputs"},caption:{en:"Type the factory into the layout designer (B = 19, L = 50, clear height 6) and read the Solution tab.",ar:"دخّل المصنع في مصمم التخطيط (B = 19، و L = 50، وارتفاع صافي 6) واقرا تبويب الحل."}},{t:"quiz",q:{kind:"num",q:{en:"In the 19 × 50 m factory, the clear distance between braced bays 1 and 6 (m)?",ar:"في المصنع 19 × 50 م، المسافة الصافية بين باكيتي الشكالات 1 و 6 (م)؟"},answer:20,tol:.001,unit:"m",explain:{en:"Bays 2 to 5 lie between them: $4\\times5 = 20$ m ≤ 25–30 m ✓.",ar:"الباكيات من 2 لـ 5 بينهم: $4\\times5 = 20$ م ≤ 25–30 م ✓."}}}]},{id:"drawings",title:{en:"The layout sheet: axes, views and line types",ar:"لوحة التخطيط: المحاور والمساقط وأنواع الخطوط"},blocks:[{t:"p",text:{en:"**Assumed sizes.** At the layout stage nothing is designed yet, so the sheet shows assumed sizes at 1:100: the truss columns as an IPE 500 — a 5 × 2 mm rectangle, its 500 mm depth in the plane of the truss — and the purlins and girts as UPN 160 channels, 1.6 mm. The design stage replaces them later.",ar:"**مقاسات مفترضة.** في مرحلة التخطيط لسه مفيش حاجة متصممة، فاللوحة بتوري مقاسات مفترضة بمقياس 1:100: أعمدة الجمالونات IPE 500 — مستطيل 5 × 2 مم، وعمقه الـ 500 مم في مستوى الجمالون — والمدادات والـ Girts مجاري UPN 160، يعني 1.6 مم. ومرحلة التصميم بتغيّرهم بعدين."}},{t:"p",text:{en:"**Axes.** Every truss line gets a letter — A, B, C … along the building — and every line across it a number — 1, 2, 3 …: the two walls, the gable-column lines and the longitudinal-bracing lines. Each view is titled by the axes it lies on. For the 19 × 50 m factory of the previous section (ten bays, two longitudinal lines) the trusses are A to K and the long lines 1 to 4, so the sheet carries *Main system, axes (B) to (J)*, *End gable, axes (A) & (K)*, *Vertical bracing, axes (1) & (4)* and *Longitudinal bracing, axes (2) & (3)*. The plan in the lab labels its axes the same way.",ar:"**المحاور.** كل خط جمالون بياخد حرف — A و B و C … بطول المبنى — وكل خط بالعرض بياخد رقم — 1 و 2 و 3 …: الحائطين، وخطوط أعمدة الواجهة، وخطوط الشكالات الطولية. وكل مسقط بيتسمّى بالمحاور اللي هو عليها. في مصنع الـ 19 × 50 م اللي في الجزء اللي فات (عشر باكيات، وخطين شكالات طولية) الجمالونات من A لـ K والخطوط الطولية من 1 لـ 4، فاللوحة فيها *النظام الرئيسي، المحاور (B) لـ (J)*، و*الواجهة الطرفية، المحاور (A) و (K)*، و*الشكالات الرأسية، المحاور (1) و (4)*، و*الشكالات الطولية، المحاور (2) و (3)*. والمسقط في المعمل بيسمّي محاوره بنفس الطريقة."}},{t:"table",head:[{en:"View",ar:"المسقط"},{en:"What it shows",ar:"بيوري إيه"}],rows:[[{en:"plan",ar:"المسقط الأفقي"},{en:"trusses, purlins (two at the ridge), roof X's, columns and the rotated gable columns; vertical and longitudinal bracing dashed in their bays",ar:"الجمالونات، والمدادات (اتنين عند الـ Ridge)، و X شكالات السقف، والأعمدة وأعمدة الواجهة ملفوفة؛ والشكالات الرأسية والطولية متقطعة في باكياتها"}],[{en:"main system",ar:"النظام الرئيسي"},{en:"one truss with its panels and its depths at the column and the ridge, the clear height, the purlins in section opening up the slope, the side wall with brick, window band and girts",ar:"جمالون واحد ببواكيه وعمقه عند العمود وعند الـ Ridge، والارتفاع الصافي، والمدادات في القطاع وفتحتها لفوق الميل، والحائط الجانبي بالطوب وشريط الشبابيك والـ Girts"}],[{en:"end gable",ar:"الواجهة الطرفية"},{en:"the end truss, the gable columns rising to its upper chord, end girts, the hatched brick dado, window band and the open door bay (a car shed has no end gable: its ends stay open)",ar:"الجمالون الطرفي، وأعمدة الواجهة طالعة لحد وتره العلوي، والـ Girts الطرفية، وحائط الطوب متهشّر، وشريط الشبابيك، وباكية الباب المفتوحة (مظلة العربيات ملهاش واجهة طرفية: أطرافها بتفضل مفتوحة)"}],[{en:"vertical bracing",ar:"الشكالات الرأسية"},{en:"the wall: columns, eave strut, the X over the clear height, the V or W in the truss-depth zone, the mid-height strut if any",ar:"الحائط: الأعمدة، وشداد الـ Eave، والـ X على الارتفاع الصافي، والـ V أو الـ W في منطقة عمق الجمالون، والعضو الأفقي في النص لو موجود"}],[{en:"longitudinal bracing",ar:"الشكالات الطولية"},{en:"one elevation per depth: purlin above, tie below, a vertical at every truss, V or W in the braced bays",ar:"واجهة لكل عمق: المداد فوق، والشداد تحت، وقائم عند كل جمالون، و V أو W في باكيات الشكالات"}]]},{t:"p",text:{en:"**Draw every bracing in every view.** A bracing member seen in a view is drawn solid; one hidden behind other members is drawn **dotted**. The main-system section therefore shows the roof bracing dotted along the upper chord, the wall bracing dotted along the columns and the longitudinal-bracing lines as dotted truss verticals, and the plan shows the vertical and longitudinal bracing dashed in their bays. A member that appears in one view only is a member the reader may miss.",ar:"**ارسم كل الشكالات في كل المساقط.** عضو الشكالات اللي باين في المسقط بيترسم خط متصل؛ واللي مستخبي ورا أعضاء تانية بيترسم **منقط (Dotted)**. علشان كده قطاع النظام الرئيسي بيوري شكالات السقف منقطة بطول الوتر العلوي، وشكالات الحوائط منقطة بطول الأعمدة، وخطوط الشكالات الطولية قوائم منقطة في الجمالون، والمسقط الأفقي بيوري الشكالات الرأسية والطولية متقطعة في باكياتها. العضو اللي باين في مسقط واحد بس ممكن اللي بيقرا اللوحة يفوّته."}},{t:"p",text:{en:"**One longitudinal-bracing elevation per depth.** Each line has its own depth $d = h + x/Z$, so it gets its own elevation; symmetric lines share one, titled with both axes. In the 19 × 50 m factory axes (2) and (3) are both 1.57 m deep → one drawing, *axes (2) & (3)*. In the 26 × 55 m shed the lines at 7.43 and 18.57 m (1.87 m) share one, and the ridge line (2.15 m) gets its own.",ar:"**واجهة شكالات طولية لكل عمق.** كل خط ليه عمقه $d = h + x/Z$، فبياخد واجهة لوحده؛ والخطوط المتماثلة بتشترك في واحدة، متسمية بالمحورين. في مصنع الـ 19 × 50 م المحورين (2) و (3) عمقهم 1.57 م الاتنين ← لوحة واحدة، *المحاور (2) و (3)*. وفي الهنجر 26 × 55 م الخطين عند 7.43 و 18.57 م (1.87 م) بيشتركوا في واحدة، وخط الـ Ridge (2.15 م) ليه واحدة لوحده."}},{t:"p",text:{en:"**Dimensions in mm.** Write repeated spacings as a product — $12\\times1583 \\approx 19\\,000$ across (the panel, 1583.3 mm, rounded to the millimetre), $10\\times5000 = 50\\,000$ along — dimension the depth at each end of the truss (1250 at the column, 1725 at the ridge) and the clear height (6000). The slope is written on the drawing as 1:20 with an arrow along the upper chord: the same slope the calculation calls 20:1.",ar:"**الأبعاد بالمم.** اكتب المسافات المتكررة كحاصل ضرب — $12\\times1583 \\approx 19\\,000$ بالعرض (الباكية، 1583.3 مم، متقربة لأقرب مم)، و $10\\times5000 = 50\\,000$ بالطول — وحط بُعد العمق عند طرفي الجمالون (1250 عند العمود، و 1725 عند الـ Ridge) والارتفاع الصافي (6000). والميل بيتكتب على اللوحة 1:20 بسهم بطول الوتر العلوي: نفس الميل اللي الحسابات بتسميه 20:1."}},{t:"p",text:{en:"**The sheet.** All five views go on one sheet inside a border: the plan at the bottom left, the vertical- and longitudinal-bracing elevations beside it, the main system and the end gable above. A **title block** in a corner gives the school or project, the drawing title, the name, section and number of the drafter, and the scale; a **notes** box above it states at least that all dimensions are in mm and the thickness of the corrugated sheets (0.5 mm).",ar:"**اللوحة.** الخمس مساقط بيترسموا على لوحة واحدة جوّه إطار: المسقط الأفقي تحت على الشمال، وواجهات الشكالات الرأسية والطولية جنبه، والنظام الرئيسي والواجهة الطرفية فوق. و**جدول بيانات اللوحة (Title block)** في ركن فيه اسم الكلية أو المشروع، وعنوان اللوحة، واسم الرسام وسكشنه ورقمه، والمقياس؛ وفوقه مربع **ملاحظات** بيقول على الأقل إن كل الأبعاد بالمم وتخانة الصاج المموج (0.5 مم)."}},{t:"quiz",q:{kind:"num",q:{en:"A longitudinal-bracing line lies 4.5 m from the wall; the truss has h = 1.25 m at the column and a 20:1 slope. Depth to write on its elevation (mm)?",ar:"خط شكالات طولية على بعد 4.5 م من الحائط؛ والجمالون h = 1.25 م عند العمود وميله 20:1. العمق اللي يتكتب على واجهته (مم)؟"},answer:1475,tol:.002,unit:"mm",explain:{en:"$d = 1.25 + 4.5/20 = 1.475$ m, written 1475 — and a line with another depth needs its own elevation.",ar:"$d = 1.25 + 4.5/20 = 1.475$ م، يتكتب 1475 — وأي خط بعمق تاني محتاج واجهة لوحده."}}}]},{id:"apply",title:{en:"Your workshop: its layout, element by element",ar:"ورشتك: تخطيطها عنصر عنصر"},blocks:[{t:"p",text:{en:"The steel workshop of your building is 12 × 18 m. Its trusses span the **12 m** (the short side ✓) at **S = 6 m** — three bays ✓. They are **triangular** (Fink-type) trusses — the span is below 24 m ✓ — rising 1.6 m from the eaves at 6.0 m to the ridge at 7.6 m (slope 1:3.75), in six panels of **a = 2.0 m** (✓ 1.5–2 m, even ✓). One rule is broken: their diagonals lie at only $\\tan^{-1}(1/3.75) = 14.9°$ and $\\tan^{-1}(2/3.75) = 28.1°$, flatter than 30°. The trusses were analysed and designed in the earlier episodes, so they carry their loads — but their flat diagonals attract large forces and long gussets. By this episode's rules a **trapezoidal N-truss** would suit the workshop better: $H = 12/12 = 1.00$ gives h below 1.25 m at both slopes, so h = 1.25 m and $H = 1.25 + 6/20 = 1.55$ m, eight panels of 1.5 m, diagonals at 39.8° and 45.9°.",ar:"ورشة الحديد في مبناك 12 × 18 م. جمالوناتها ماشية على الـ **12 م** (الضلع القصير ✓) كل **S = 6 م** — تلات باكيات ✓. وهي جمالونات **مثلثة** (نوع Fink) — البحر أقل من 24 م ✓ — بتعلى 1.6 م من الـ Eaves عند 6.0 م للـ Ridge عند 7.6 م (ميل 1:3.75)، في ست بواكي **a = 2.0 م** (✓ من 1.5 لـ 2 م، وزوجي ✓). فيه قاعدة واحدة مكسورة: أقطارها زاويتها $\\tan^{-1}(1/3.75) = 14.9°$ و $\\tan^{-1}(2/3.75) = 28.1°$ بس، أفلطح من 30°. الجمالونات اتحللت واتصممت في الحلقات اللي فاتت، فهي شايلة أحمالها — لكن أقطارها المفلطحة بتجذب قوى كبيرة وألواح وصلة (Gusset) طويلة. وبقواعد الحلقة دي **جمالون N شبه منحرف** كان هيناسب الورشة أكتر: $H = 12/12 = 1.00$ بتدّي h أقل من 1.25 م في الميلين، يبقى h = 1.25 م و $H = 1.25 + 6/20 = 1.55$ م، وتمن بواكي كل واحدة 1.5 م، والأقطار عند 39.8° و 45.9°."}},{t:"table",head:[{en:"Element",ar:"العنصر"},{en:"In your workshop",ar:"في ورشتك"},{en:"Rule",ar:"القاعدة"}],rows:[[{en:"columns",ar:"الأعمدة"},{en:"HEB 300, 6.0 m, fixed bases, web in the truss plane",ar:"HEB 300، ارتفاع 6.0 م، قواعد ثابتة، والعصب في مستوى الجمالون"},{en:"strong axis across",ar:"المحور القوي بالعرض"}],[{en:"purlins",ar:"المدادات"},{en:"on every top joint, 2.0 m apart, spanning 6 m",ar:"على كل عقدة علوية، كل 2.0 م، وبحرها 6 م"},{en:"a = 1.5–2 m ✓",ar:"a = 1.5–2 م ✓"}],[{en:"roof bracing",ar:"شكالات السقف"},{en:"both end bays (1 and 3), 6 m apart",ar:"الباكيتين الطرفيتين (1 و 3)، بينهم 6 م"},{en:"≤ 25–30 m ✓",ar:"≤ 25–30 م ✓"}],[{en:"vertical bracing",ar:"الشكالات الرأسية"},{en:"in the same bays, both walls; one X at 45°, with a strut at 3.0 m through its crossing, continuous along each wall",ar:"في نفس الباكيات، على الحائطين؛ X واحدة بزاوية 45°، وعضو أفقي عند 3.0 م بيعدّي من تقاطعها، مستمر بطول كل حائط"},{en:"clear height 6.0 m ≥ 6 m: strut at mid-height",ar:"الارتفاع الصافي 6.0 م ≥ 6 م: عضو أفقي في نص الارتفاع"}],[{en:"longitudinal ties",ar:"الشدادات الطولية"},{en:"at 4 and 8 m (joints b2, b4)",ar:"عند 4 و 8 م (العقد b2 و b4)"},{en:"≤ 8 m ✓",ar:"≤ 8 م ✓"}],[{en:"gable columns and girts",ar:"أعمدة الواجهة والـ Girts"},{en:"on the tie lines, 4 m apart; girts at 2.0, 3.0, 4.5, 6.0 m",ar:"على خطوط الشدادات، كل 4 م؛ والـ Girts عند 2.0 و 3.0 و 4.5 و 6.0 م"},{en:"5–8 m (closer here, to meet the ties)",ar:"5–8 م (أقرب هنا علشان تقابل الشدادات)"}],[{en:"crane runway",ar:"مجرى الونش"},{en:"crane girders on column brackets at 4.6 m",ar:"كمرات ونش على كوابيل الأعمدة عند 4.6 م"},{en:"braking → vertical bracing",ar:"الفرامل ← الشكالات الرأسية"}]],caption:{en:"The building model draws the wall X of bay 1 and the 3.0 m strut along each wall; by the rule the twin X sits in bay 3.",ar:"نموذج المبنى راسم الـ X بتاعة الحوائط في الباكية 1 والعضو الأفقي عند 3.0 م بطول كل حائط؛ وبالقاعدة الـ X التوأم في الباكية 3."}},{t:"lab",lab:"shed",height:500,props:{preset:"workshop",missions:d,defaultTab:"results"},caption:{en:"Your workshop in the Steel Shed Explorer: switch to Layout, find the broken rule, then try the trapezoidal truss.",ar:"ورشتك في مستكشف الهناجر: حوّل للتخطيط، ولاقي القاعدة المكسورة، وبعدين جرّب الجمالون شبه المنحرف."}},{t:"widget",w:"building",props:{focus:"WC-1-L",tags:["ws-columns","ws-trusses","ws-purlins","ws-bracing","ws-crane","ws-layout"]}},{t:"quiz",q:{kind:"num",q:{en:"Your workshop: the angle of its flattest diagonal (degrees)?",ar:"ورشتك: زاوية أفلطح قطري فيها (بالدرجات)؟"},answer:14.93,tol:.003,unit:"°",explain:{en:"It rises one panel's rise over one panel: $\\tan^{-1}(1/3.75) = 14.9°$, well below 30°.",ar:"بيعلى قد ارتفاع باكية على طول باكية: $\\tan^{-1}(1/3.75) = 14.9°$، أقل بكتير من 30°."}}}]}],quiz:[{kind:"num",q:{en:"A 24 m span: the depth at mid-span taken as span/12 (m)?",ar:"بحر 24 م: العمق في النص على أساس البحر/12 (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"$24/12 = 2.00$ m (span/16 would give 1.50 m).",ar:"$24/12 = 2.00$ م (والبحر/16 كان هيدّي 1.50 م)."}},{kind:"num",q:{en:"The same truss (H = 2.0 m, span 24 m) at a slope of 20:1: h at the column (m)?",ar:"نفس الجمالون (H = 2.0 م، بحر 24 م) بميل 20:1: h عند العمود (م)؟"},answer:1.4,tol:.003,unit:"m",explain:{en:"$h = 2.0 - 12/20 = 1.40$ m ≥ 1.25 ✓ (10:1 would give 0.80 m ✗).",ar:"$h = 2.0 - 12/20 = 1.40$ م ≥ 1.25 ✓ (والـ 10:1 كانت هتدّي 0.80 م ✗)."}},{kind:"mcq",q:{en:"The main trusses of a rectangular shed span…",ar:"الجمالونات الرئيسية في هنجر مستطيل ماشية…"},options:[{en:"the short direction",ar:"في الاتجاه القصير"},{en:"the long direction",ar:"في الاتجاه الطويل"},{en:"either, it makes no difference",ar:"أي واحد، مش فارقة"}],answer:0,explain:{en:"The truss is the costly element: give it the shorter span and cover the length with purlins and bracing.",ar:"الجمالون هو العنصر الغالي: ادّيله البحر الأقصر وغطّي الطول بالمدادات والشكالات."}},{kind:"num",q:{en:"A 22.4 m span with a target panel of 1.6 m: the (even) number of panels?",ar:"بحر 22.4 م والباكية المطلوبة 1.6 م: عدد البواكي (الزوجي)؟"},answer:14,tol:.001,explain:{en:"$22.4/1.6 = 14$, already even: a = 1.60 m.",ar:"$22.4/1.6 = 14$، زوجي أصلًا: a = 1.60 م."}},{kind:"tf",q:{en:"A shed on reinforced-concrete columns still needs vertical X bracing in its walls.",ar:"الهنجر اللي على أعمدة خرسانة مسلحة لسه محتاج شكالات X رأسية في حوائطه."},answer:!1,explain:{en:"The concrete columns (and their frames) carry the horizontal loads to the ground; the roof and longitudinal bracing are still needed.",ar:"الأعمدة الخرسانية (وإطاراتها) بتنزّل الأحمال الأفقية للأرض؛ لكن شكالات السقف والطولية لسه لازمين."}},{kind:"num",q:{en:"A 30 m span: the least number of longitudinal-bracing lines (at most 8 m apart)?",ar:"بحر 30 م: أقل عدد خطوط شكالات طولية (مش أبعد من 8 م)؟"},answer:3,tol:.001,explain:{en:"Two lines leave 10 m gaps; three lines leave 7.5 m: 3.",ar:"خطين بيسيبوا 10 م؛ وتلاتة بيسيبوا 7.5 م: يبقى 3."}},{kind:"mcq",q:{en:"Which pair works together in the same bays?",ar:"أنهي اتنين بيشتغلوا مع بعض في نفس الباكيات؟"},options:[{en:"roof bracing and vertical bracing",ar:"شكالات السقف والشكالات الرأسية"},{en:"roof bracing and the girts",ar:"شكالات السقف والـ Girts"},{en:"vertical bracing and the purlins",ar:"الشكالات الرأسية والمدادات"}],answer:0,explain:{en:"The roof bracing hands its reactions to the vertical bracing at the eaves of the same bay.",ar:"شكالات السقف بتسلّم ردود أفعالها للشكالات الرأسية عند الـ Eaves في نفس الباكية."}},{kind:"num",q:{en:"A 45 m shed of 9 bays of 5 m, braced in both end bays: the clear distance between them (m)?",ar:"هنجر 45 م فيه 9 باكيات كل واحدة 5 م، وشكالات في الباكيتين الطرفيتين: المسافة الصافية بينهم (م)؟"},answer:35,tol:.001,unit:"m",explain:{en:"$7\\times5 = 35$ m > 30 m: brace the middle bay 5 as well (two gaps of 15 m).",ar:"$7\\times5 = 35$ م > 30 م: اعمل شكالات في الباكية 5 اللي في النص كمان (مسافتين كل واحدة 15 م)."}}]};export{c as default};
